import type { Lang } from '@/lib/i18n/translations';
type LangMap = Record<Lang, string>;
const E: Omit<LangMap, 'en'> = { ms: '', tur: '', urd: '', ben: '', fas: '', zh: '', yue: '', ja: '', ru: '', es: '', ko: '', ta: '', si: '' };

export const SLEEP_CONTENT = {
  wudu_h: { en: `Wudu Before Sleep`, ms: `Wudhu Sebelum Tidur`, tur: `Uykudan Önce Abdest`, urd: `سونے سے پہلے وضو`, ben: `ঘুমানোর পূর্বে ওযু`, fas: `وضو پیش از خواب`, zh: `寝前小净`, yue: `寢前小淨`, ja: `就寝前のウドゥー`, ru: `Омовение перед сном`, es: `Wudu antes de dormir`, ko: `잠자기 전 우두`, ta: `உறங்குமுன் உளூ`, si: `නින්දට පෙර වුදූ` },
  wudu_p1: { en: `The Prophet ﷺ said: "When you go to your bed, perform wudu as you would for the prayer, then lie down on your right side."`, ms: `Nabi ﷺ bersabda: "Apabila kamu pergi ke tempat tidurmu, ambillah wudhu sebagaimana wudhu untuk solat, kemudian baringlah di atas sisi kananmu."`, tur: `Peygamber ﷺ buyurdu: "Yatağına gittiğinde namaz için aldığın gibi abdest al, sonra sağ tarafına uzan."`, urd: `نبی ﷺ نے فرمایا: "جب تم اپنے بستر پر جاؤ تو نماز کی طرح وضو کرو، پھر دائیں کروٹ پر لیٹ جاؤ۔"`, ben: `নবী ﷺ বলেছেন: "যখন তুমি বিছানায় যাও, নামাযের ন্যায় ওযু কর, তারপর ডান পাশে শুয়ে পড়।"`, fas: `پیامبر ﷺ فرمود: «چون به بستر خود می‌روی، همانند وضوی نماز، وضو بگیر و بر پهلوی راست بخواب.»`, zh: `先知 ﷺ 云：「汝入床之时，如礼拜之小净而净之，继以右侧卧。」`, yue: `先知 ﷺ 云：「汝入床之時，如禮拜之小淨而淨之，繼以右側臥。」`, ja: `預言者 ﷺ は仰せられた。「床に就くときは、礼拝のためのウドゥーのようにウドゥーを行い、それから右を下にして横たわりなさい。」`, ru: `Пророк ﷺ сказал: «Когда идёшь в постель, соверши омовение, как для молитвы, затем ляг на правый бок».`, es: `El Profeta ﷺ dijo: «Cuando vayas a tu cama, haz el wudu como para la oración, y luego acuéstate sobre tu lado derecho.»`, ko: `예언자 ﷺ 께서 말씀하시길: "잠자리에 들 때는 예배의 우두처럼 우두를 행하고, 그런 다음 오른쪽으로 누워라."`, ta: `நபி ﷺ கூறினார்: "நீ படுக்கைக்குச் செல்லும்போது, தொழுகைக்கான உளூவைப் போல் உளூச் செய்து, பின்னர் வலப் புறமாகப் படுத்துக்கொள்."`, si: `නබි ﷺ තුමා පැවසුවා: "ඔබ නිදන යහන වෙත යන විට, නමස්කාරය සඳහා වුදූ කරන ආකාරයට වුදූ කර, පසුව දකුණු පැත්තට හැරී වැතිර සිටින්න."` },
  wudu_p2: { en: `Sleeping in a state of ritual purity is a Sunnah mu'akkadah. The scholars mention that the soul in sleep is presented before Allah, and being purified is a mark of honour for that state. If you cannot make wudu (illness, injury), tayamum suffices; if neither is possible, sleep in whatever state you are in, with no sin.`, ms: `Tidur dalam keadaan suci ialah Sunnah muakkadah. Ulama menyebut roh dalam tidur dibentangkan di hadapan Allah, dan bersuci adalah tanda kemuliaan untuk keadaan itu. Jika tidak mampu berwudhu (sakit, cedera), tayammum memadai; jika kedua-duanya tidak mampu, tidurlah dalam apa keadaan sekalipun, tanpa dosa.`, tur: `Abdestli uyumak sünnet-i müekkededir. Âlimler, uykudaki ruhun Allah'a arz olunduğunu, temiz olarak bulunmanın o hâl için bir şeref alâmeti olduğunu belirtir. Abdest alınamıyorsa (hastalık, yaralanma) teyemmüm yeter; her ikisi de mümkün değilse hangi hâldeysen öyle uyu, günah olmaz.`, urd: `طہارت کی حالت میں سونا سنت مؤکدہ ہے۔ علماء نے ذکر کیا کہ نیند میں روح اللہ کے سامنے پیش کی جاتی ہے، اور اس حالت کے لیے طہارت شرافت کی علامت ہے۔ اگر وضو ممکن نہ ہو (بیماری، چوٹ) تو تیمم کافی ہے؛ اگر دونوں ممکن نہ ہوں تو جس حالت میں ہو سو جاؤ، کوئی گناہ نہیں۔`, ben: `পবিত্র অবস্থায় ঘুমানো একটি সুন্নাহ মুয়াক্কাদা। আলিমগণ বলেছেন যে ঘুমে আত্মা আল্লাহর সামনে পেশ করা হয়, এবং সেই অবস্থার জন্য পবিত্র থাকা সম্মানের চিহ্ন। যদি ওযু করতে না পার (অসুস্থতা, আঘাত) তায়াম্মুম যথেষ্ট; যদি দুটোই সম্ভব না হয়, যে অবস্থায় আছ সেই অবস্থায় ঘুমাও, কোনো গুনাহ নেই।`, fas: `خفتن با طهارت سنت مؤکده است. علما گفته‌اند روح در خواب بر خدا عرضه می‌شود و پاک بودن نشانه‌ی شرافت آن حال است. اگر وضو ممکن نیست (بیماری، جراحت) تیمم کافی است؛ اگر هیچ‌کدام مقدور نبود، در هر حالتی هستی بخواب و گناهی نیست.`, zh: `以清净之身而寝，属圣行之强调者。学者言灵魂于寝中呈于真主前，此时清净乃彼状之尊号。若无法小净（患病、受伤），干净土代之即可；若二者皆不能，随汝之状而寝，无罪。`, yue: `以清淨之身而寢，屬聖行之強調者。學者言靈魂於寢中呈於真主前，此時清淨乃彼狀之尊號。若無法小淨（患病、受傷），乾淨土代之即可；若二者皆不能，隨汝之狀而寢，無罪。`, ja: `清浄な状態で眠ることは強調されたスンナである。学者たちは、眠りにある魂はアッラーに供され、その状態にあって清浄であることは名誉の徴だと述べる。ウドゥーが叶わないなら（病、負傷）タヤンムムで足り、いずれも叶わなければそのままの状態で眠ってよく、罪はない。`, ru: `Спать в состоянии ритуальной чистоты, сунна муаккада. Учёные упоминают, что душа во сне предстаёт перед Аллахом, и быть очищенным в этом состоянии, знак чести. Если не можешь совершить омовение (болезнь, травма), достаточно таяммума; если ни то, ни другое невозможно, спи в каком есть состоянии, без греха.`, es: `Dormir en estado de pureza ritual es Sunna muakkadah. Los sabios mencionan que el alma en el sueño es presentada ante Al-lah, y estar purificado es una marca de honor para ese estado. Si no puedes hacer wudu (enfermedad, herida), basta el tayammum; si ninguno es posible, duerme como estés, sin pecado.`, ko: `정결한 상태로 자는 것은 강조된 순나다. 학자들은 잠 속의 영혼이 알라 앞에 제시되며, 그 상태에서 정결한 것은 명예의 표징이라 언급한다. 우두를 할 수 없다면(질병, 부상) 타야뭄으로 충분하며, 둘 다 불가능하면 있는 그대로 자되 죄가 없다.`, ta: `தூய்மையான நிலையில் உறங்குதல் ஸுன்னா முஅக்கதா. அறிஞர்கள் கூறுகிறார்கள்: உறக்கத்தில் ஆன்மா அல்லாஹ்வின் முன் சமர்ப்பிக்கப்படுகிறது, அந்நிலைக்கு தூய்மையாக இருப்பது கண்ணியத்தின் அடையாளம். உளூச் செய்ய முடியாவிட்டால் (நோய், காயம்) தயம்மம் போதுமானது; இரண்டும் இயலாவிட்டால், எந்த நிலையிலும் உறங்குக, பாவம் இல்லை.`, si: `පිරිසිදු තත්ත්වයේ නිදා ගැනීම බලවත් සුන්නාවකි. නින්දේදී ආත්මය අල්ලාහ් හමුවේ ඉදිරිපත් වන බවත්, එම තත්ත්වයේ පිරිසිදුවීම එයට ගෞරවයේ ලක්‍ෂණයක් බවත් විද්වත්හු පවසති. වුදූ කළ නොහැකි නම් (රෝගය, තුවාල), තයම්මුම් ප්‍රමාණවත්; දෙකම නොහැකි නම්, එසේ නිදන්න, පාපයක් නොවේ.` },
  wudu_source: { en: `Source: al-Bukhari 247, Muslim 2710 (al-Bara ibn Azib).`, ms: `Sumber: al-Bukhari 247, Muslim 2710 (al-Bara ibn Azib).`, tur: `Kaynak: Buhârî 247, Müslim 2710 (el-Berâ' ibn Âzib).`, urd: `ماخذ: بخاری ۲۴۷، مسلم ۲۷۱۰ (البراء بن عازب)۔`, ben: `উৎস: বুখারি ২৪৭, মুসলিম ২৭১০ (আল-বারা ইবন আযিব)।`, fas: `منبع: بخاری ۲۴۷، مسلم ۲۷۱۰ (البراء بن عازب).`, zh: `出处：布哈里 247、穆斯林 2710（艾勒·白拉·本·阿齐布）。`, yue: `出處：布哈里 247、穆斯林 2710（艾勒·白拉·本·阿齊布）。`, ja: `出典：ブハーリー 247、ムスリム 2710（アル＝バラー・イブン・アージブ）。`, ru: `Источник: аль-Бухари 247, Муслим 2710 (аль-Бара ибн Азиб).`, es: `Fuente: al-Bukhari 247, Muslim 2710 (al-Bara ibn Azib).`, ko: `출처: 알부카리 247, 무슬림 2710 (알바라 이븐 아지브).`, ta: `மூலம்: புகாரி 247, முஸ்லிம் 2710 (அல்-பராஉ இப்னு ஆஸிப்).`, si: `මූලාශ්‍රය: බුකාරි 247, මුස්ලිම් 2710 (අල්-බරා ඉබ්න් ආසිබ්).` },
  right_h: { en: `The Sunnah Posture: Right Side`, ms: `Kedudukan Sunnah: Sisi Kanan`, tur: `Sünnete Uygun Duruş: Sağ Yan`, urd: `سنت کی حالت: دائیں کروٹ`, ben: `সুন্নাহর ভঙ্গি: ডান পাশ`, fas: `حالتِ سنت: پهلوی راست`, zh: `圣行姿势：右侧卧`, yue: `聖行姿勢：右側臥`, ja: `スンナの姿勢：右を下に`, ru: `Поза по Сунне: правый бок`, es: `La postura Sunna: sobre el lado derecho`, ko: `순나의 자세: 오른쪽으로`, ta: `ஸுன்னா நிலை: வலப் புறம்`, si: `සුන්නා ඉරියව්ව: දකුණු පැත්ත` },
  right_p1: { en: `The Sunnah is to lie on the right side, placing the right hand under the right cheek. Sleeping on the back is permitted (and mentioned in some ahadith) but the initial posture on going to bed is the right side.`, ms: `Sunnahnya ialah berbaring pada sisi kanan, meletakkan tangan kanan di bawah pipi kanan. Tidur menelentang dibenarkan (dan disebut dalam beberapa hadis) tetapi kedudukan permulaan ketika naik ke tempat tidur ialah sisi kanan.`, tur: `Sünnet olan sağ yan üzeri yatmak, sağ eli sağ yanağın altına koymaktır. Sırt üstü uyumak câizdir (bazı hadislerde geçer), fakat yatağa uzanırken başlangıç duruşu sağ yandır.`, urd: `سنت یہ ہے کہ دائیں کروٹ پر لیٹا جائے اور دایاں ہاتھ دائیں گال کے نیچے رکھا جائے۔ چٹ لیٹنا جائز ہے (اور بعض احادیث میں مذکور ہے) لیکن بستر پر جاتے وقت ابتدائی حالت دائیں کروٹ ہے۔`, ben: `সুন্নাহ হলো ডান পাশে শোয়া, ডান হাত ডান গালের নিচে রাখা। চিৎ হয়ে ঘুমানো অনুমোদিত (এবং কিছু হাদিসে উল্লেখিত) কিন্তু বিছানায় যাওয়ার প্রাথমিক ভঙ্গি হলো ডান পাশ।`, fas: `سنت آن است که بر پهلوی راست بخوابید و دست راست را زیر گونهٔ راست بگذارید. خفتن به پشت جایز است (و در برخی احادیث آمده) اما وضعیت آغازینِ ورود به بستر، پهلوی راست است.`, zh: `圣行乃右侧卧，以右手垫右颊。仰卧亦准（有传述记之），然入床之初仍以右侧卧为始。`, yue: `聖行乃右側臥，以右手墊右頰。仰臥亦準（有傳述記之），然入床之初仍以右側臥為始。`, ja: `スンナは右を下にして横になり、右手を右頬の下に置くこと。仰向けに眠るのも許されるが（一部のハディースにある）、寝床に就く際の最初の姿勢は右側である。`, ru: `Сунна, лежать на правом боку, положив правую руку под правую щёку. Спать на спине дозволено (и упомянуто в некоторых хадисах), но начальная поза при отходе ко сну, на правом боку.`, es: `La Sunna es acostarse sobre el lado derecho, colocando la mano derecha bajo la mejilla derecha. Dormir boca arriba es permitido (y mencionado en algunos hadices), pero la postura inicial al ir a la cama es sobre el lado derecho.`, ko: `순나는 오른쪽으로 누워 오른손을 오른쪽 뺨 아래에 두는 것이다. 등을 대고 자는 것은 허용되며(일부 하디스에 언급된다) 그러나 잠자리에 들 때 처음의 자세는 오른쪽이다.`, ta: `ஸுன்னா என்பது வலப் புறமாகப் படுத்து, வலது கையை வலது கன்னத்திற்கு அடியில் வைத்திருப்பதாகும். மல்லாந்து படுத்து உறங்குதல் அனுமதிக்கப்பட்டது (சில ஹதீஸ்களில் குறிப்பிடப்பட்டுள்ளது), ஆனால் படுக்கைக்குச் செல்லும் ஆரம்ப நிலை வலப் புறமாகவே இருக்க வேண்டும்.`, si: `සුන්නාව යනු දකුණු පැත්තට හැරී වැතිර, දකුණු අත දකුණු කම්මුලට යටින් තැබීමයි. පිට උඩ නිදාගැනීම අනුමතයි (සමහර හදීස්වල සඳහන් වේ), නමුත් යහනට යන විට ආරම්භක ඉරියව්ව දකුණු පැත්තයි.` },
  right_p2: { en: `Hudhayfah (ra) said: "When the Prophet ﷺ went to his bed at night he would place his hand under his cheek and say 'Bismika Allahumma amutu wa ahya' ..."`, ms: `Hudhaifah (ra) berkata: "Apabila Nabi ﷺ pergi ke tempat tidurnya pada waktu malam, baginda meletakkan tangannya di bawah pipinya dan mengucapkan 'Bismika Allahumma amutu wa ahya' ..."`, tur: `Huzeyfe (r.a.) buyurdu: "Peygamber ﷺ gece yatağına vardığında elini yanağının altına koyar ve 'Bismike'l-Lâhümme emûtü ve ahyâ' derdi."`, urd: `حذیفہ (رض) نے فرمایا: "جب نبی ﷺ رات کو اپنے بستر پر جاتے، اپنا ہاتھ گال کے نیچے رکھتے اور فرماتے 'بِسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا' ..."`, ben: `হুযাইফা (রা) বলেন: "নবী ﷺ যখন রাতে বিছানায় যেতেন, তিনি তাঁর হাত গালের নিচে রেখে বলতেন: 'বিসমিকা আল্লাহুম্মা আমুতু ওয়া আহইয়া' ..."`, fas: `حذیفه (رض) گفت: «هرگاه پیامبر ﷺ شب به بستر می‌رفت، دست خویش را زیر گونه می‌نهاد و می‌گفت: بسمک اللهم أموت وأحیا ...»`, zh: `胡宰法（愿主喜之）云：「先知 ﷺ 夜入床时，即以手垫颊，云『奉主之名，我死我生』……」`, yue: `胡宰法（願主喜之）云：「先知 ﷺ 夜入床時，即以手墊頰，云『奉主之名，我死我生』……」`, ja: `フザイファ（ラ）は言われた。「預言者 ﷺ は夜、寝床に就かれると、手を頬の下に置き『ビスミカ・アッラーフンマ・アムートゥ・ワ・アフヤー』と唱えられた……」`, ru: `Хузайфа (ра) сказал: «Когда Пророк ﷺ ночью ложился в постель, он клал руку под щёку и говорил: «Би-сми-ка Аллахумма амуту ва ахья»...»`, es: `Hudhayfah (ra) dijo: «Cuando el Profeta ﷺ iba a su cama por la noche, ponía la mano bajo la mejilla y decía: 'Bismika Al-lahumma amutu wa ahya' ...»`, ko: `후자이파(라)께서 말씀하시길: "예언자 ﷺ 께서 밤에 잠자리에 드시면 손을 뺨 아래에 두시고 '비스미카 알라훔마 아무투 와 아흐야'라고 말씀하셨다..."`, ta: `ஹுதைஃபா (ரலி) கூறினார்: "நபி ﷺ இரவில் தமது படுக்கைக்குச் சென்றால், தமது கையை தமது கன்னத்திற்கு அடியில் வைத்து 'பிஸ்மிக அல்லாஹும்ம அமூது வ அஹ்யா' என்று சொல்வார்..."`, si: `හුදෛෆා (රළි) පැවසුවා: "නබි ﷺ තුමා රාත්‍රියේ තමන්ගේ යහන වෙත ගොස්, තමන්ගේ අත කම්මුලට යටින් තබා 'බිස්මික අල්ලාහුම්ම අමූතු ව අහ්යා' යැයි කියතී..."` },
  right_p3: { en: `Sleeping face-down is explicitly discouraged. Abu Umama narrates the Prophet ﷺ passing a man lying on his stomach and saying: "This is a posture Allah does not love."`, ms: `Tidur meniarap ditegah secara jelas. Abu Umamah meriwayatkan Nabi ﷺ melintasi seorang lelaki yang berbaring di atas perutnya lalu bersabda: "Ini kedudukan yang tidak disukai Allah."`, tur: `Yüzükoyun uyumak açıkça hoş görülmemiştir. Ebû Ümâme, Peygamber'in ﷺ karnı üzerine yatan birinin yanından geçerken şöyle buyurduğunu nakleder: "Bu, Allah'ın sevmediği bir yatış şeklidir."`, urd: `منہ کے بل سونا واضح طور پر ناپسند ہے۔ ابو امامہ روایت کرتے ہیں کہ نبی ﷺ ایک آدمی کے پاس سے گزرے جو پیٹ کے بل لیٹا تھا اور فرمایا: "یہ ایسی حالت ہے جسے اللہ پسند نہیں فرماتا۔"`, ben: `উপুড় হয়ে ঘুমানো স্পষ্টভাবে অপছন্দনীয়। আবু উমামা বর্ণনা করেন, নবী ﷺ পেটের উপর শুয়ে থাকা এক ব্যক্তির পাশ দিয়ে যাচ্ছিলেন এবং বললেন: "এটি এমন এক ভঙ্গি যা আল্লাহ পছন্দ করেন না।"`, fas: `خوابیدن به رو صریحاً ناپسند شمرده شده است. ابوامامه روایت می‌کند که پیامبر ﷺ از کنار مردی که بر شکم خفته بود گذشت و فرمود: «این حالتی است که خدا دوست ندارد.»`, zh: `俯睡明为不喜。艾布·乌马麦传述先知 ﷺ 经一人俯卧，言曰：「此乃真主不喜之姿。」`, yue: `俯睡明為不喜。艾布·烏馬麥傳述先知 ﷺ 經一人俯臥，言曰：「此乃真主不喜之姿。」`, ja: `うつ伏せに眠ることは明確に嫌われている。アブー・ウマーマは、預言者 ﷺ が腹ばいに横たわる男の傍を通りかかり「これはアッラーがお好みにならぬ姿である」と仰せられたと伝える。`, ru: `Спать лицом вниз явно порицаемо. Абу Умама передаёт, что Пророк ﷺ, проходя мимо мужчины, лежавшего на животе, сказал: «Это поза, которую Аллах не любит».`, es: `Dormir boca abajo está explícitamente desaconsejado. Abu Umama narra que el Profeta ﷺ pasó junto a un hombre acostado boca abajo y dijo: «Ésta es una postura que Al-lah no ama.»`, ko: `엎드려 자는 것은 명백히 권장되지 않는다. 아부 우마마는 예언자 ﷺ 께서 배를 대고 누운 한 남자 옆을 지나시며 "이는 알라께서 좋아하지 않으시는 자세이다"라고 말씀하신 것을 전한다.`, ta: `முகம் கீழ் நோக்கி உறங்குதல் தெளிவாக வெறுக்கத் தக்கது. அபூ உமாமா அறிவிக்கிறார்: நபி ﷺ வயிற்றின்மேல் படுத்திருந்த ஒரு மனிதனை கடந்து சென்று கூறினார்: "இது அல்லாஹ் விரும்பாத நிலை."`, si: `මුහුණ පහළට තබා නිදාගැනීම පැහැදිලිවම නොකැමති කරන ලදී. නබි ﷺ තුමා බඩ මත වැතිර සිටි මිනිසෙකු අසලින් යද්දී 'මෙය අල්ලාහ් ප්‍රිය නොකරන ඉරියව්වකි' යැයි වදාළ බව අබූ උමාමා වාර්තා කරයි.` },
  right_source: { en: `Sources: al-Bukhari 6314 (Hudhayfah), Abu Dawud 5040 and Ibn Majah 3723 for the face-down prohibition.`, ms: `Sumber: al-Bukhari 6314 (Hudhaifah), Abu Dawud 5040 dan Ibn Majah 3723 untuk larangan tidur meniarap.`, tur: `Kaynaklar: Buhârî 6314 (Huzeyfe), yüzükoyun yatma yasağı için Ebû Dâvud 5040 ve İbn Mâce 3723.`, urd: `ماخذ: بخاری ۶۳۱۴ (حذیفہ)، منہ کے بل سونے کی ممانعت کے لیے ابو داود ۵۰۴۰ اور ابن ماجہ ۳۷۲۳۔`, ben: `উৎস: বুখারি ৬৩১৪ (হুযাইফা), উপুড় হয়ে ঘুমানোর নিষেধ সম্পর্কে আবু দাউদ ৫০৪০ ও ইবন মাজাহ ৩৭২৩।`, fas: `منابع: بخاری ۶۳۱۴ (حذیفه)، برای نهی از خوابیدن به رو ابوداود ۵۰۴۰ و ابن ماجه ۳۷۲۳.`, zh: `出处：布哈里 6314（胡宰法），俯睡之禁则见艾布·达乌德 5040 与伊本·马哲 3723。`, yue: `出處：布哈里 6314（胡宰法），俯睡之禁則見艾布·達烏德 5040 與伊本·馬哲 3723。`, ja: `出典：ブハーリー 6314（フザイファ）、うつ伏せ寝の禁止についてはアブー・ダーウード 5040 とイブン・マージャ 3723。`, ru: `Источники: аль-Бухари 6314 (Хузайфа); о запрете спать лицом вниз, Абу Дауд 5040 и Ибн Маджа 3723.`, es: `Fuentes: al-Bukhari 6314 (Hudhayfah); para la prohibición de dormir boca abajo, Abu Dawud 5040 e Ibn Maja 3723.`, ko: `출처: 알부카리 6314 (후자이파); 엎드려 자는 것의 금지는 아부 다우드 5040과 이븐 마자 3723.`, ta: `மூலங்கள்: புகாரி 6314 (ஹுதைஃபா); முகம் கீழ் நோக்கி உறங்குதலின் தடைக்கு அபூ தாவூத் 5040 மற்றும் இப்னு மாஜா 3723.`, si: `මූලාශ්‍ර: බුකාරි 6314 (හුදෛෆා); මුහුණ පහළට තබා නිදාගැනීමේ තහනම සඳහා අබූ දාවූද් 5040 සහ ඉබ්න් මාජා 3723.` },
  pre_h: { en: `The Du'a Before Sleeping`, ms: `Doa Sebelum Tidur`, tur: `Uykudan Önceki Duâ`, urd: `سونے سے پہلے کی دعا`, ben: `ঘুমানোর পূর্বের দোয়া`, fas: `دعای پیش از خواب`, zh: `寝前之祷`, yue: `寢前之禱`, ja: `就寝前の祈願`, ru: `Дуа перед сном`, es: `La Du'a antes de dormir`, ko: `잠들기 전 두아`, ta: `உறங்குமுன் பிரார்த்தனை`, si: `නින්දට පෙර දුආව` },
  pre_translit: { en: `Bismika Allahumma amutu wa ahya.`, ms: `Bismika Allahumma amutu wa ahya.`, tur: `Bismike'l-Lâhümme emûtü ve ahyâ.`, urd: `بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا۔`, ben: `বিসমিকা আল্লাহুম্মা আমুতু ওয়া আহইয়া।`, fas: `بسمک اللهم أموت وأحیا.`, zh: `比斯米卡·安拉呼曼·阿姆图·瓦·阿哈亚。`, yue: `比斯米卡·安拉呼曼·阿姆圖·瓦·阿哈亞。`, ja: `ビスミカ・アッラーフンマ・アムートゥ・ワ・アフヤー。`, ru: `Би-сми-ка Аллахумма амуту ва ахья.`, es: `Bismika Al-lahumma amutu wa ahya.`, ko: `비스미카 알라훔마 아무투 와 아흐야.`, ta: `பிஸ்மிக அல்லாஹும்ம அமூது வ அஹ்யா.`, si: `බිස්මික අල්ලාහුම්ම අමූතු ව අහ්යා.` },
  pre_meaning: { en: `In Your name, O Allah, I die and I live.`, ms: `Dengan nama-Mu, ya Allah, aku mati dan aku hidup.`, tur: `Ey Allah'ım! Senin adınla ölür ve senin adınla dirilirim.`, urd: `اے اللہ! تیرے نام سے میں مرتا ہوں اور تیرے نام سے جیتا ہوں۔`, ben: `হে আল্লাহ! আপনার নামে আমি মরি এবং আপনার নামে বাঁচি।`, fas: `به نامِ تو ای خدای من، می‌میرم و زنده می‌شوم.`, zh: `真主啊！奉你之名，我死我生。`, yue: `真主啊！奉你之名，我死我生。`, ja: `アッラーよ、御身の御名によりて、われは死し、われは生く。`, ru: `Именем Твоим, о Аллах, я умираю и я живу.`, es: `En Tu nombre, oh Al-lah, muero y vivo.`, ko: `오 알라시여! 당신의 이름으로 저는 죽고 저는 삽니다.`, ta: `உன் பெயரால், யா அல்லாஹ்! நான் இறக்கிறேன், நான் வாழ்கிறேன்.`, si: `අහෝ අල්ලාහ්! ඔබේ නාමයෙන් මම මිය යමි, ඔබේ නාමයෙන් මම ජීවත් වෙමි.` },
  pre_p: { en: `A concise du'a placing life and death, waking and sleep, entirely in Allah's hand. The Prophet ﷺ used it every night.`, ms: `Doa ringkas yang menyerahkan hidup dan mati, jaga dan tidur, sepenuhnya kepada Allah. Nabi ﷺ mengamalkannya setiap malam.`, tur: `Hayatı ve ölümü, uyanıklığı ve uykuyu tamamen Allah'ın eline bırakan kısa bir duâdır. Peygamber ﷺ her gece bunu okurdu.`, urd: `ایک مختصر دعا جو زندگی و موت، بیداری و نیند کو مکمل طور پر اللہ کے ہاتھ میں رکھ دیتی ہے۔ نبی ﷺ ہر رات اسے پڑھتے تھے۔`, ben: `একটি সংক্ষিপ্ত দোয়া যা জীবন ও মৃত্যু, জাগরণ ও ঘুম, সম্পূর্ণরূপে আল্লাহর হাতে সঁপে দেয়। নবী ﷺ প্রতি রাতে এটি পড়তেন।`, fas: `دعایی کوتاه که زندگی و مرگ، بیداری و خواب را یکسره به دستِ خدا می‌سپارد. پیامبر ﷺ هر شب آن را می‌خواند.`, zh: `此简短之祷，将生死、寐醒尽付真主之手。先知 ﷺ 每夜诵之。`, yue: `此簡短之禱，將生死、寐醒盡付真主之手。先知 ﷺ 每夜誦之。`, ja: `生と死、目覚めと眠りを、そのままアッラーの御手にゆだねる簡潔な祈願である。預言者 ﷺ は毎夜これを唱えられた。`, ru: `Краткая дуа, полностью вверяющая жизнь и смерть, пробуждение и сон в руки Аллаха. Пророк ﷺ произносил её каждую ночь.`, es: `Una du'a concisa que pone la vida y la muerte, la vigilia y el sueño, enteramente en la mano de Al-lah. El Profeta ﷺ la decía cada noche.`, ko: `삶과 죽음, 깨어남과 잠을 온전히 알라의 손에 맡기는 간결한 두아. 예언자 ﷺ 께서는 매일 밤 이를 낭송하셨다.`, ta: `வாழ்வையும் இறப்பையும், விழிப்பையும் உறக்கத்தையும் முழுவதுமாக அல்லாஹ்வின் கையில் ஒப்படைக்கும் சுருக்கமான பிரார்த்தனை. நபி ﷺ ஒவ்வொரு இரவும் இதைச் சொல்வார்.`, si: `ජීවිතය හා මරණය, අවදිය හා නින්ද සම්පූර්ණයෙන්ම අල්ලාහ්ගේ අතට පවරන කෙටි දුආවකි. නබි ﷺ තුමා සෑම රාත්‍රියකම මෙය කීහ.` },
  pre_source: { en: `Source: al-Bukhari 6314, 6324 (Hudhayfah); Bukhari 6312 has the waking counterpart.`, ms: `Sumber: al-Bukhari 6314, 6324 (Hudhaifah); Bukhari 6312 mengandungi doa bangun tidur yang sepadan.`, tur: `Kaynak: Buhârî 6314, 6324 (Huzeyfe); uyanış duası için Buhârî 6312.`, urd: `ماخذ: بخاری ۶۳۱۴، ۶۳۲۴ (حذیفہ)؛ جاگنے کی دعا کے لیے بخاری ۶۳۱۲۔`, ben: `উৎস: বুখারি ৬৩১৪, ৬৩২৪ (হুযাইফা); জাগরণের দোয়া বুখারি ৬৩১২-এ।`, fas: `منبع: بخاری ۶۳۱۴، ۶۳۲۴ (حذیفه)؛ دعای بیداری در بخاری ۶۳۱۲.`, zh: `出处：布哈里 6314、6324（胡宰法）；起身之祷见布哈里 6312。`, yue: `出處：布哈里 6314、6324（胡宰法）；起身之禱見布哈里 6312。`, ja: `出典：ブハーリー 6314、6324（フザイファ）；目覚めの祈願はブハーリー 6312。`, ru: `Источник: аль-Бухари 6314, 6324 (Хузайфа); дуа при пробуждении, аль-Бухари 6312.`, es: `Fuente: al-Bukhari 6314, 6324 (Hudhayfah); la du'a al despertar está en al-Bukhari 6312.`, ko: `출처: 알부카리 6314, 6324 (후자이파); 깨어남의 두아는 알부카리 6312.`, ta: `மூலம்: புகாரி 6314, 6324 (ஹுதைஃபா); விழிக்கும் பிரார்த்தனை புகாரி 6312.`, si: `මූලාශ්‍රය: බුකාරි 6314, 6324 (හුදෛෆා); අවදිවීමේ දුආව බුකාරි 6312.` },
  recite_h: { en: `The Prophetic Recitations at Bedtime`, ms: `Bacaan Nabi Sebelum Tidur`, tur: `Uyumadan Önce Peygamber ﷺ'in Okuduğu Sûre ve Âyetler`, urd: `سونے سے پہلے نبی ﷺ کی تلاوتیں`, ben: `ঘুমানোর পূর্বে নবী ﷺ-এর তিলাওয়াতসমূহ`, fas: `تلاوت‌های پیامبر ﷺ پیش از خواب`, zh: `寝前之圣行诵读`, yue: `寢前之聖行誦讀`, ja: `就寝前の預言者 ﷺ の朗誦`, ru: `Пророческие чтения перед сном`, es: `Las recitaciones proféticas antes de dormir`, ko: `잠들기 전 예언자 ﷺ 의 낭송`, ta: `உறங்குமுன் நபி ﷺ அவர்களின் ஓதுதல்கள்`, si: `නින්දට පෙර නබි ﷺ තුමන්ගේ පාරායනා` },
  recite_1_label: { en: `1. Ayat al-Kursi`, ms: `1. Ayat al-Kursi`, tur: `1. Âyetü'l-Kürsî`, urd: `۱۔ آیت الکرسی`, ben: `১. আয়াতুল কুরসি`, fas: `۱. آیة الکرسی`, zh: `一、宝座之节`, yue: `一、寶座之節`, ja: `一、玉座の節（アーヤトゥル＝クルスィー）`, ru: `1. Аят аль-Курси`, es: `1. Ayat al-Kursi`, ko: `1. 아야트 알쿠르시`, ta: `1. ஆயதுல் குர்ஸி`, si: `1. ආයතුල් කුර්සී` },
  recite_1_body: { en: `Whoever recites Ayat al-Kursi at night has an appointed guardian from Allah, and no shaytan comes near them until morning.`, ms: `Sesiapa membaca Ayat al-Kursi pada waktu malam, Allah menetapkan penjaga baginya, dan tiada syaitan yang mendekatinya sehingga pagi.`, tur: `Kim geceleyin Âyetü'l-Kürsî'yi okursa, Allah tarafından üzerine bir bekçi görevlendirilir ve sabaha kadar hiçbir şeytan yaklaşamaz.`, urd: `جو رات کو آیت الکرسی پڑھے، اللہ کی طرف سے ایک نگہبان مقرر ہو جاتا ہے، اور صبح تک کوئی شیطان اس کے قریب نہیں آتا۔`, ben: `যে ব্যক্তি রাতে আয়াতুল কুরসি পড়ে, আল্লাহর পক্ষ থেকে তার জন্য একজন রক্ষক নিযুক্ত হন, এবং সকাল পর্যন্ত কোনো শয়তান তার কাছে আসতে পারে না।`, fas: `هر که شب آیة الکرسی را بخواند، از سوی خدا نگهبانی برای او گمارده می‌شود و تا صبح شیطانی به او نزدیک نمی‌شود.`, zh: `凡夜诵宝座之节者，真主赐一守护者，直至清晨无恶魔敢近。`, yue: `凡夜誦寶座之節者，真主賜一守護者，直至清晨無惡魔敢近。`, ja: `夜にアーヤトゥル＝クルスィーを唱えた者には、アッラーから守護者が定められ、朝までいかなるシャイターンも近づかない。`, ru: `Кто прочтёт аят аль-Курси на ночь, тому от Аллаха назначается страж, и ни один шайтан не приблизится к нему до утра.`, es: `Quien recite Ayat al-Kursi por la noche, tiene un guardián designado por Al-lah, y ningún shaytán se le acerca hasta la mañana.`, ko: `밤에 아야트 알쿠르시를 낭송하는 자에게는 알라께서 지정하신 수호자가 있으며, 아침까지 어떤 샤이딴도 그에게 다가오지 못한다.`, ta: `இரவில் ஆயதுல் குர்ஸியை ஓதுபவருக்கு அல்லாஹ்விடமிருந்து ஒரு காவலர் நியமிக்கப்படுகிறார், மேலும் காலை வரை எந்த ஷைத்தானும் அவரை நெருங்குவதில்லை.`, si: `රාත්‍රියේ ආයතුල් කුර්සී කියවන අයට අල්ලාහ්ගෙන් රැකවලෙක් පත් කරනු ලබන අතර, උදෑසන දක්වා කිසිදු ෂෙයිතාන්කු ඔහුට ළං නොවේ.` },
  recite_1_source: { en: `Source: al-Bukhari 5010 (Abu Hurayra).`, ms: `Sumber: al-Bukhari 5010 (Abu Hurairah).`, tur: `Kaynak: Buhârî 5010 (Ebû Hüreyre).`, urd: `ماخذ: بخاری ۵۰۱۰ (ابو ہریرہ)۔`, ben: `উৎস: বুখারি ৫০১০ (আবু হুরায়রা)।`, fas: `منبع: بخاری ۵۰۱۰ (ابوهریره).`, zh: `出处：布哈里 5010（艾布·胡赖赖）。`, yue: `出處：布哈里 5010（艾布·胡賴賴）。`, ja: `出典：ブハーリー 5010（アブー・フライラ）。`, ru: `Источник: аль-Бухари 5010 (Абу Хурайра).`, es: `Fuente: al-Bukhari 5010 (Abu Hurayra).`, ko: `출처: 알부카리 5010 (아부 후라이라).`, ta: `மூலம்: புகாரி 5010 (அபூ ஹுரைரா).`, si: `මූලාශ්‍රය: බුකාරි 5010 (අබූ හුරෛරා).` },
  recite_2_label: { en: `2. The Last Two Verses of al-Baqarah`, ms: `2. Dua Ayat Terakhir Surah al-Baqarah`, tur: `2. Bakara Sûresi'nin Son İki Âyeti`, urd: `۲۔ سورۃ البقرہ کی آخری دو آیات`, ben: `২. সূরা আল-বাকারার শেষ দুই আয়াত`, fas: `۲. دو آیهٔ آخر سورهٔ بقره`, zh: `二、黄牛章末二节`, yue: `二、黃牛章末二節`, ja: `二、雌牛章の最後の二節`, ru: `2. Два последних аята суры аль-Бакара`, es: `2. Los dos últimos versículos de al-Baqarah`, ko: `2. 알바카라의 마지막 두 절`, ta: `2. அல்-பகராவின் இறுதி இரு வசனங்கள்`, si: `2. අල්-බකරාහ්ගේ අවසන් වාක්‍ය දෙක` },
  recite_2_body: { en: `The Prophet ﷺ said: "Whoever recites the two verses at the end of Surat al-Baqarah at night, they will suffice him."`, ms: `Nabi ﷺ bersabda: "Sesiapa membaca dua ayat di akhir surah al-Baqarah pada waktu malam, ia mencukupkannya."`, tur: `Peygamber ﷺ buyurdu: "Kim geceleyin Bakara Sûresi'nin sonundaki iki âyeti okursa, o ona kâfî gelir."`, urd: `نبی ﷺ نے فرمایا: "جو رات کو سورۃ البقرہ کی آخری دو آیات پڑھے، وہ اس کے لیے کافی ہو جاتی ہیں۔"`, ben: `নবী ﷺ বলেছেন: "যে ব্যক্তি রাতে সূরা আল-বাকারার শেষ দুই আয়াত পড়ে, তা তার জন্য যথেষ্ট হবে।"`, fas: `پیامبر ﷺ فرمود: «هر که شب دو آیهٔ آخر سورهٔ بقره را بخواند، او را کفایت می‌کند.»`, zh: `先知 ﷺ 云：「凡夜诵黄牛章末二节者，此足其用。」`, yue: `先知 ﷺ 云：「凡夜誦黃牛章末二節者，此足其用。」`, ja: `預言者 ﷺ は仰せられた。「夜に雌牛章の最後の二節を唱える者には、それが十分となる。」`, ru: `Пророк ﷺ сказал: «Кто прочтёт два аята в конце суры аль-Бакара на ночь, они ему довлеют».`, es: `El Profeta ﷺ dijo: «A quien recite por la noche los dos versículos del final de Surat al-Baqarah, le bastarán.»`, ko: `예언자 ﷺ 께서 말씀하시길: "밤에 알바카라 마지막 두 절을 낭송하는 자에게는 그것이 족하리라."`, ta: `நபி ﷺ கூறினார்: "இரவில் ஸூரத்துல் பகராவின் இறுதி இரு வசனங்களை ஓதுபவருக்கு, அவை போதுமானவை."`, si: `නබි ﷺ තුමා පැවසුවා: "රාත්‍රියේ අල්-බකරාහ්ගේ අවසන් වාක්‍ය දෙක කියවන අයට, ඒවා ඔහුට ප්‍රමාණවත් වේ."` },
  recite_2_source: { en: `Source: al-Bukhari 4008, Muslim 807 (Abu Mas'ud).`, ms: `Sumber: al-Bukhari 4008, Muslim 807 (Abu Mas'ud).`, tur: `Kaynak: Buhârî 4008, Müslim 807 (Ebû Mes'ûd).`, urd: `ماخذ: بخاری ۴۰۰۸، مسلم ۸۰۷ (ابو مسعود)۔`, ben: `উৎস: বুখারি ৪০০৮, মুসলিম ৮০৭ (আবু মাসউদ)।`, fas: `منبع: بخاری ۴۰۰۸، مسلم ۸۰۷ (ابومسعود).`, zh: `出处：布哈里 4008、穆斯林 807（艾布·麦斯欧德）。`, yue: `出處：布哈里 4008、穆斯林 807（艾布·麥斯歐德）。`, ja: `出典：ブハーリー 4008、ムスリム 807（アブー・マスウード）。`, ru: `Источник: аль-Бухари 4008, Муслим 807 (Абу Мас'уд).`, es: `Fuente: al-Bukhari 4008, Muslim 807 (Abu Mas'ud).`, ko: `출처: 알부카리 4008, 무슬림 807 (아부 마스우드).`, ta: `மூலம்: புகாரி 4008, முஸ்லிம் 807 (அபூ மஸ்ஊத்).`, si: `මූලාශ්‍රය: බුකාරි 4008, මුස්ලිම් 807 (අබූ මස්ඌද්).` },
  recite_3_label: { en: `3. al-Ikhlas + al-Falaq + al-Nas, three times each, blowing into the palms`, ms: `3. Al-Ikhlas + al-Falaq + al-Nas, tiga kali setiap satu, sambil meniup ke tapak tangan`, tur: `3. İhlâs + Felâk + Nâs, üçer defa, avuçlara üflenerek`, urd: `۳۔ الاخلاص + الفلق + الناس، ہر ایک تین بار، ہتھیلیوں میں پھونک کر`, ben: `৩. আল-ইখলাস + আল-ফালাক + আন-নাস, প্রত্যেকটি তিনবার, হাতের তালুতে ফুঁ দিয়ে`, fas: `۳. اخلاص + فلق + ناس، هر یک سه بار، با دمیدن در کف دستان`, zh: `三、忠诚章、晨曦章、世人章各三遍，吹于双掌`, yue: `三、忠誠章、晨曦章、世人章各三遍，吹於雙掌`, ja: `三、イフラース、ファラク、ナースを各三回、両手のひらに吹き込みながら`, ru: `3. Аль-Ихлас + аль-Фаляк + ан-Нас, каждая по три раза, с обдуванием ладоней`, es: `3. Al-Ijlas + al-Falaq + al-Nas, tres veces cada una, soplando en las palmas`, ko: `3. 알이클라스 + 알팔라크 + 알나스, 각 세 번씩, 손바닥에 불면서`, ta: `3. அல்-இக்லாஸ் + அல்-ஃபலக் + அன்-நாஸ், ஒவ்வொன்றும் மூன்று முறை, உள்ளங்கைகளில் ஊதி`, si: `3. අල්-ඉක්ලාස්, අල්-ෆලක් සහ අන්-නාස්, එකින් තුන් වතාවක් ලෙස, අත්ල දෙකට පිඹ` },
  recite_3_body: { en: `'Aisha (ra) reported that every night before sleep the Prophet ﷺ would join his palms, blow into them, and recite Qul huwa Allahu Ahad, Qul a'udhu bi rabbi-l falaq, and Qul a'udhu bi rabbi-n nas, then wipe them over as much of his body as he could reach, beginning with the head, face, and front of his body. He did this three times.`, ms: `'Aisyah (ra) meriwayatkan bahawa setiap malam sebelum tidur, Nabi ﷺ menghimpunkan kedua tapak tangannya, meniupnya, dan membaca Qul huwa Allahu Ahad, Qul a'udhu bi rabbi-l falaq, dan Qul a'udhu bi rabbi-n nas, kemudian menyapunya ke seluruh tubuh baginda sedaya mungkin, bermula dengan kepala, wajah, dan bahagian hadapan tubuh. Baginda melakukannya sebanyak tiga kali.`, tur: `Hz. Âişe (r.a.) rivayet eder ki: her gece uykudan önce Peygamber ﷺ avuçlarını birleştirir, onlara üfler, "Kul hüvellâhü ahad", "Kul e'ûzü bi rabbi'l-felak" ve "Kul e'ûzü bi rabbi'n-nâs" sûrelerini okur, sonra bu avuçları bedeninin ulaşabildiği her yerine, başından, yüzünden ve ön tarafından başlayarak sürerdi. Bunu üç defa yapardı.`, urd: `عائشہ (رض) روایت کرتی ہیں کہ ہر رات سونے سے پہلے نبی ﷺ اپنی ہتھیلیاں ملا کر ان میں پھونکتے، پھر «قل هو الله أحد»، «قل أعوذ برب الفلق» اور «قل أعوذ برب الناس» پڑھتے، پھر اپنے جسم کے جتنے حصے تک ہاتھ پہنچ سکتے، سر، چہرہ اور جسم کے سامنے کے حصے سے شروع کر کے پھیرتے۔ یہ عمل تین بار کرتے۔`, ben: `আয়িশা (রা) বর্ণনা করেন যে প্রতি রাতে ঘুমানোর পূর্বে নবী ﷺ তাঁর হাতের তালু মিলিয়ে সেগুলোতে ফুঁ দিতেন, «কুল হুয়াল্লাহু আহাদ», «কুল আউযু বিরাব্বিল ফালাক» ও «কুল আউযু বিরাব্বিন নাস» পড়তেন, তারপর দেহের যতটুকু পৌঁছাতে পারতেন সেই অংশে, মাথা, মুখ এবং দেহের সামনের অংশ থেকে শুরু করে, বুলিয়ে দিতেন। এটি তিনবার করতেন।`, fas: `عایشه (رض) روایت می‌کند که هر شب پیش از خواب پیامبر ﷺ کف دستان خویش را به هم می‌آورد، در آنها می‌دمید و «قل هو الله أحد»، «قل أعوذ برب الفلق» و «قل أعوذ برب الناس» را می‌خواند، سپس بر آنچه از پیکر خویش می‌رسید، از سر و چهره و پیشِ بدن آغاز کرده، می‌مالید. این کار را سه بار انجام می‌داد.`, zh: `阿伊莎（愿主喜之）传述：每夜寝前，先知 ﷺ 双掌相合而吹之，诵「他就是真主，独一之主」、「我求护于晨曦之主」、「我求护于世人之主」，继以两掌抹身，尽其所及，自首、面及身之前部起，如此三遍。`, yue: `阿伊莎（願主喜之）傳述：每夜寢前，先知 ﷺ 雙掌相合而吹之，誦「他就是真主，獨一之主」、「我求護於晨曦之主」、「我求護於世人之主」，繼以兩掌抹身，盡其所及，自首、面及身之前部起，如此三遍。`, ja: `アーイシャ（ラ）は伝える。毎夜就寝前、預言者 ﷺ は両手のひらを合わせ、そこに息を吹きかけ、「クル・フワッラーフ・アハド」「クル・アウーズ・ビ・ラッビル＝ファラク」「クル・アウーズ・ビ・ラッビン＝ナース」を唱えられた。そののち手の届く限りの身体を、頭、顔、そして身体の前面から始めて撫でられた。これを三度行われた。`, ru: `'Аиша (ра) сообщает, что каждую ночь перед сном Пророк ﷺ соединял ладони, дул в них, читал «Куль хуваЛлаху Ахад», «Куль а'узу би-Раббиль-фаляк» и «Куль а'узу би-Раббин-нас», затем проводил ими по телу, куда только достигал, начиная с головы, лица и передней части тела. Так делал трижды.`, es: `'Aisha (ra) relató que cada noche antes de dormir el Profeta ﷺ unía las palmas de las manos, soplaba en ellas y recitaba Qul huwa Allahu Ahad, Qul a'udhu bi rabbi-l falaq y Qul a'udhu bi rabbi-n nas; después se las pasaba por cuanto podía alcanzar del cuerpo, empezando por la cabeza, el rostro y el frente del cuerpo. Lo hacía tres veces.`, ko: `아이샤(라)께서 전하시길: 매일 밤 잠들기 전에 예언자 ﷺ 께서는 두 손바닥을 모아 그 위에 입김을 부시고 「꿀 후왈라후 아하드」, 「꿀 아우두 비랍비-ㄹ 팔라크」, 「꿀 아우두 비랍빈-나스」를 낭송하신 뒤, 손이 닿는 몸의 모든 부위, 머리·얼굴·몸의 앞부분부터 시작하여 문지르셨다. 이를 세 번 반복하셨다.`, ta: `ஆயிஷா (ரலி) அறிவிக்கிறார்: ஒவ்வொரு இரவும் உறங்குமுன் நபி ﷺ இரு உள்ளங்கைகளையும் சேர்த்து அவற்றில் ஊதி, «குல் ஹுவல்லாஹு அஹத்», «குல் அஊது பி ரப்பில் ஃபலக்» மற்றும் «குல் அஊது பி ரப்பின் நாஸ்» ஆகியவற்றை ஓதுவார், பின்னர் தலை, முகம் மற்றும் உடலின் முன்பகுதியிலிருந்து தொடங்கி, அடையக்கூடிய உடலின் அனைத்து பகுதிகளிலும் அவற்றைத் தேய்ப்பார். இதை மூன்று முறை செய்வார்.`, si: `ආඉෂා (රළි) වාර්තා කරයි: සෑම රාත්‍රියකම නින්දට පෙර නබි ﷺ තුමා තමන්ගේ අත්ල දෙක එක්කර, ඒවාට පිඹ, «කුල් හුවල්ලාහු අහද්», «කුල් අඌඡු බි රබ්බිල් ෆලක්» සහ «කුල් අඌඡු බි රබ්බින් නාස්» කියවා, පසුව හිසින්, මුහුණින් සහ ශරීරයේ ඉදිරි කොටසින් ආරම්භ කරමින්, තමන්ට අත ලං කළ හැකි සෑම තැනකම ඒවා පිරිමැදින. මෙය තෙවරක් සිදු කළහ.` },
  recite_3_source: { en: `Source: al-Bukhari 5017 ('Aisha).`, ms: `Sumber: al-Bukhari 5017 ('Aisyah).`, tur: `Kaynak: Buhârî 5017 (Âişe).`, urd: `ماخذ: بخاری ۵۰۱۷ (عائشہ)۔`, ben: `উৎস: বুখারি ৫০১৭ (আয়িশা)।`, fas: `منبع: بخاری ۵۰۱۷ (عایشه).`, zh: `出处：布哈里 5017（阿伊莎）。`, yue: `出處：布哈里 5017（阿伊莎）。`, ja: `出典：ブハーリー 5017（アーイシャ）。`, ru: `Источник: аль-Бухари 5017 ('Аиша).`, es: `Fuente: al-Bukhari 5017 ('Aisha).`, ko: `출처: 알부카리 5017 (아이샤).`, ta: `மூலம்: புகாரி 5017 (ஆயிஷா).`, si: `මූලාශ්‍රය: බුකාරි 5017 (ආඉෂා).` },
  recite_4_label: { en: `4. Dust off the bed three times`, ms: `4. Kebaskan tempat tidur tiga kali`, tur: `4. Yatağı üç defa silkelemek`, urd: `۴۔ بستر کو تین بار جھاڑنا`, ben: `৪. বিছানা তিনবার ঝেড়ে নেওয়া`, fas: `۴. سه بار تکاندنِ بستر`, zh: `四、以衣角掸床三次`, yue: `四、以衣角撣床三次`, ja: `四、寝床を三度払う`, ru: `4. Смахнуть с постели три раза`, es: `4. Sacudir la cama tres veces`, ko: `4. 이불을 세 번 털어내기`, ta: `4. படுக்கையை மூன்று முறை உதறுதல்`, si: `4. යහන තුන් වතාවක් උඩුකුරු කිරීම` },
  recite_4_body: { en: `Abu Hurayra (ra) reported: "When any of you goes to his bed, let him take a corner of his lower garment and dust off his bed with it three times, and let him say 'Bismillah', for he does not know what has come onto it after him."`, ms: `Abu Hurairah (ra) meriwayatkan: "Apabila salah seorang daripada kamu pergi ke tempat tidurnya, hendaklah dia mengambil hujung kain sarungnya, mengebaskan tempat tidurnya tiga kali dan mengucapkan 'Bismillah', kerana dia tidak tahu apa yang telah datang ke atasnya selepasnya."`, tur: `Ebû Hüreyre (r.a.) rivayet eder: "Sizden biri yatağına gittiğinde, izarının bir ucunu alıp yatağını onunla üç defa silkelesin ve 'Bismillâh' desin. Çünkü kendisi yokken yatağına ne geldiğini bilmez."`, urd: `ابو ہریرہ (رض) نے فرمایا: "جب تم میں سے کوئی اپنے بستر پر جائے تو اپنے کپڑے کا کنارہ لے کر اس سے بستر کو تین بار جھاڑے اور 'بسم اللہ' کہے، کیونکہ اسے معلوم نہیں کہ اس کے بعد وہاں کیا آیا ہو۔"`, ben: `আবু হুরায়রা (রা) বর্ণনা করেন: "তোমাদের কেউ যখন বিছানায় যায়, সে তার লুঙ্গির কোণ দিয়ে বিছানা তিনবার ঝেড়ে নেবে এবং 'বিসমিল্লাহ' বলবে, কারণ সে জানে না তার অনুপস্থিতিতে সেখানে কী এসেছে।"`, fas: `ابوهریره (رض) روایت می‌کند: «چون یکی از شما به بستر خود می‌رود، گوشه‌ای از ازارش را بگیرد و با آن سه بار بسترش را بتکاند و «بسم الله» بگوید، زیرا نمی‌داند پس از او چه چیزی بر آن آمده است.»`, zh: `艾布·胡赖赖（愿主喜之）云：「汝等入床之时，宜以下裳一角掸床三次，并诵『奉真主之名』；因汝不知汝去后何物入其上。」`, yue: `艾布·胡賴賴（願主喜之）云：「汝等入床之時，宜以下裳一角撣床三次，並誦『奉真主之名』；因汝不知汝去後何物入其上。」`, ja: `アブー・フライラ（ラ）は伝える。「あなたがたの誰かが寝床に就くとき、下衣の裾を取り、それで寝床を三度払い、『ビスミッラー』と唱えなさい。あなたが離れていた間にそこに何が入り込んだか分からないからである。」`, ru: `Абу Хурайра (ра) передал: «Когда кто-либо из вас идёт в свою постель, пусть возьмёт край нижней одежды и трижды смахнёт им постель, произнеся «Бисмиллях», ибо не знает, что попало на неё в его отсутствие».`, es: `Abu Hurayra (ra) transmitió: «Cuando alguno de vosotros vaya a su cama, tome un extremo de su prenda inferior, sacuda con él la cama tres veces y diga 'Bismillah', pues no sabe qué ha caído sobre ella en su ausencia.»`, ko: `아부 후라이라(라)께서 전하시길: "너희 중 누구라도 잠자리에 들 때는 아랫옷 자락을 잡고 그것으로 침상을 세 번 털어낸 뒤 '비스밀라'라고 말하라. 그가 없는 사이 그 위에 무엇이 놓였는지 알지 못하기 때문이다."`, ta: `அபூ ஹுரைரா (ரலி) அறிவிக்கிறார்: "உங்களில் ஒருவர் தமது படுக்கைக்குச் செல்லும்போது, தமது இழுவாடையின் ஓரத்தை எடுத்து அதனால் படுக்கையை மூன்று முறை உதறி 'பிஸ்மில்லாஹ்' என்று சொல்லட்டும், ஏனெனில் அவர் இல்லாத போது அதன்மேல் என்ன வந்திருக்கிறது என்பது அவருக்குத் தெரியாது."`, si: `අබූ හුරෛරා (රළි) පැවසුවා: "ඔබ අතරින් කිසිවෙකු තමන්ගේ යහන වෙත යන විට, තමන්ගේ පහළ ඇඳුමේ කෙළවර ගෙන එයින් යහන තුන් වතාවක් තැළියි, පසුව 'බිස්මිල්ලාහ්' යැයි කියයි; මන්ද ඔහු නොසිටියදී එය මත කුමක් පැමිණියේද ඔහු නොදනී."` },
  recite_4_source: { en: `Source: al-Bukhari 6320, Muslim 2714.`, ms: `Sumber: al-Bukhari 6320, Muslim 2714.`, tur: `Kaynak: Buhârî 6320, Müslim 2714.`, urd: `ماخذ: بخاری ۶۳۲۰، مسلم ۲۷۱۴۔`, ben: `উৎস: বুখারি ৬৩২০, মুসলিম ২৭১৪।`, fas: `منبع: بخاری ۶۳۲۰، مسلم ۲۷۱۴.`, zh: `出处：布哈里 6320、穆斯林 2714。`, yue: `出處：布哈里 6320、穆斯林 2714。`, ja: `出典：ブハーリー 6320、ムスリム 2714。`, ru: `Источник: аль-Бухари 6320, Муслим 2714.`, es: `Fuente: al-Bukhari 6320, Muslim 2714.`, ko: `출처: 알부카리 6320, 무슬림 2714.`, ta: `மூலம்: புகாரி 6320, முஸ்லிம் 2714.`, si: `මූලාශ්‍රය: බුකාරි 6320, මුස්ලිම් 2714.` },
  bad_h: { en: `On Waking From a Bad Dream`, ms: `Ketika Terjaga daripada Mimpi Buruk`, tur: `Kötü Rüyadan Uyanınca`, urd: `برے خواب سے جاگنے پر`, ben: `দুঃস্বপ্ন থেকে জেগে ওঠার সময়`, fas: `هنگام بیدار شدن از خواب بد`, zh: `恶梦醒后`, yue: `惡夢醒後`, ja: `悪夢から目覚めたとき`, ru: `При пробуждении от дурного сна`, es: `Al despertar de un mal sueño`, ko: `악몽에서 깨어났을 때`, ta: `கெட்ட கனவிலிருந்து விழிக்கும்போது`, si: `නරක සිහිනයෙන් අවදි වන විට` },
  bad_p1: { en: `The Prophet ﷺ said: "A good dream is from Allah, and a bad dream is from the shaytan. If any of you sees what he dislikes, let him spit lightly to his left three times when he wakes up, seek refuge in Allah from its evil, and not mention it to anyone. It will not harm him."`, ms: `Nabi ﷺ bersabda: "Mimpi yang baik daripada Allah, dan mimpi yang buruk daripada syaitan. Sekiranya salah seorang daripada kamu bermimpi sesuatu yang dibencinya, hendaklah dia meludah kecil ke sebelah kirinya tiga kali apabila terjaga, memohon perlindungan kepada Allah daripada keburukannya, dan tidak menceritakan kepada sesiapa. Ia tidak akan memudaratkannya."`, tur: `Peygamber ﷺ buyurdu: "Güzel rüya Allah'tandır, kötü rüya şeytandandır. Sizden biri hoşlanmadığı bir şey görürse, uyandığında sol tarafına hafifçe üç kere üflesin, kötülüğünden Allah'a sığınsın ve kimseye anlatmasın. O rüya ona zarar vermez."`, urd: `نبی ﷺ نے فرمایا: "اچھا خواب اللہ کی طرف سے ہے، اور برا خواب شیطان کی طرف سے۔ جب تم میں سے کوئی ایسا خواب دیکھے جو اسے ناپسند ہو، تو جاگنے پر تین بار اپنی بائیں طرف ہلکا سا تھوکے، اس کے شر سے اللہ کی پناہ مانگے، اور کسی کو نہ بتائے۔ وہ اسے نقصان نہ پہنچائے گا۔"`, ben: `নবী ﷺ বলেছেন: "ভালো স্বপ্ন আল্লাহর পক্ষ থেকে, আর দুঃস্বপ্ন শয়তানের পক্ষ থেকে। তোমাদের কেউ যদি এমন কিছু দেখে যা সে অপছন্দ করে, তাহলে জেগে ওঠার পর সে যেন তিনবার তার বাম দিকে হালকাভাবে থুতু ফেলে, তার অনিষ্ট থেকে আল্লাহর নিকট আশ্রয় প্রার্থনা করে এবং কাউকে না জানায়। তা তার কোনো ক্ষতি করবে না।"`, fas: `پیامبر ﷺ فرمود: «رؤیای نیک از خداست و رؤیای بد از شیطان. هر یک از شما چیزی ناخوشایند دید، هنگام بیداری سه بار به سمت چپ خود آب دهان اندازد، از شرّ آن به خدا پناه برد و به کسی نگوید. آن رؤیا زیانی به او نخواهد رساند.»`, zh: `先知 ﷺ 云：「善梦自真主，恶梦自恶魔。若汝之一人梦其所恶，醒时向左轻吐三下，求主护己之恶，勿告他人，梦不害之。」`, yue: `先知 ﷺ 云：「善夢自真主，惡夢自惡魔。若汝之一人夢其所惡，醒時向左輕吐三下，求主護己之惡，勿告他人，夢不害之。」`, ja: `預言者 ﷺ は仰せられた。「良い夢はアッラーからのもの、悪い夢はシャイターンからのものである。あなたがたの誰かが嫌う夢を見たら、目が覚めたとき左に軽く三度唾を吐き、その悪よりアッラーに加護を求め、誰にも語ってはならない。その夢は害を及ぼさない。」`, ru: `Пророк ﷺ сказал: «Добрый сон, от Аллаха, а дурной, от шайтана. Если кто из вас увидит то, что ему неприятно, пусть, проснувшись, легко трижды сплюнет налево, прибегнет к Аллаху от его зла и никому о нём не расскажет. Он не повредит ему».`, es: `El Profeta ﷺ dijo: «El buen sueño es de Al-lah, y el mal sueño es del shaytán. Si alguno de vosotros ve algo que le disgusta, al despertar escupa suavemente a su izquierda tres veces, refúgiese en Al-lah de su mal, y no lo cuente a nadie. No le dañará.»`, ko: `예언자 ﷺ 께서 말씀하시길: "좋은 꿈은 알라께로부터이며, 나쁜 꿈은 샤이딴으로부터이다. 너희 중 누구라도 싫어하는 꿈을 꾸었다면, 잠에서 깨어난 뒤 왼쪽으로 세 번 가볍게 침을 뱉고, 그 악으로부터 알라께 피난을 구하며, 아무에게도 언급하지 말라. 그 꿈은 그를 해치지 못하리라."`, ta: `நபி ﷺ கூறினார்: "நல்ல கனவு அல்லாஹ்விடமிருந்து, கெட்ட கனவு ஷைத்தானிடமிருந்து. உங்களில் ஒருவர் தான் விரும்பாத ஒன்றைக் கண்டால், விழிக்கும்போது தமது இடப் புறமாக மூன்று முறை மெதுவாக துப்பட்டும், அதன் தீங்கிலிருந்து அல்லாஹ்விடம் அடைக்கலம் தேட்டும், யாருக்கும் கூறவேண்டாம். அது அவரை பாதிக்காது."`, si: `නබි ﷺ තුමා පැවසුවා: "යහපත් සිහිනය අල්ලාහ්ගෙන්ය, නරක සිහිනය ෂෙයිතාන්ගෙන්ය. ඔබ අතරින් කිසිවෙකු අප්‍රියමත් දෙයක් දුටුවේ නම්, අවදි වූ පසු වම් පසට තුන් වතාවක් සැහැල්ලුවෙන් කෙළ ගසා, එහි නපුරෙන් අල්ලාහ්ගෙන් රැකවරණය පතා, කිසිවෙකුට එය නොකියන්න. එය ඔහුට හානියක් නොකරයි."` },
  bad_translit: { en: `A'udhu billahi mina-sh shaytani-r rajim.`, ms: `A'udhu billahi minash-shaytanir-rajim.`, tur: `E'ûzü billâhi mine'ş-şeytâni'r-racîm.`, urd: `أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ۔`, ben: `আউযু বিল্লাহি মিনাশ শাইতানির রাজিম।`, fas: `أعوذ بالله من الشیطان الرجیم.`, zh: `阿吾祖比拉希敏勒沙伊塔尼勒拉吉姆。`, yue: `阿吾祖比拉希敏勒沙伊塔尼勒拉吉姆。`, ja: `アウーズビッラーヒ・ミナッ＝シャイターニル＝ラジーム。`, ru: `А'узу биЛляхи мина-ш-шайтани-р-раджим.`, es: `A'udhu billahi min ash-shaytani-r rajim.`, ko: `아우두 빌라히 미나쉬 샤이따니르 라짐.`, ta: `அஊது பில்லாஹி மினஷ் ஷைதானிர் ரஜீம்.`, si: `අඌඡු බිල්ලාහි මිනෂ් ෂෙයිතානිර් රජීම්.` },
  bad_meaning: { en: `I seek refuge with Allah from the accursed shaytan.`, ms: `Aku berlindung kepada Allah daripada syaitan yang direjam.`, tur: `Kovulmuş şeytanın şerrinden Allah'a sığınırım.`, urd: `میں مردود شیطان سے اللہ کی پناہ چاہتا ہوں۔`, ben: `আমি বিতাড়িত শয়তান থেকে আল্লাহর নিকট আশ্রয় প্রার্থনা করছি।`, fas: `از شیطان راندهٔ درگاه به خدا پناه می‌برم.`, zh: `我求真主护佑，免于被逐之恶魔。`, yue: `我求真主護佑，免於被逐之惡魔。`, ja: `われは呪われしシャイターンよりアッラーに加護を求む。`, ru: `Прибегаю к Аллаху от проклятого шайтана.`, es: `Me refugio en Al-lah del shaytán maldito.`, ko: `저는 저주받은 샤이딴으로부터 알라께 피난을 구합니다.`, ta: `சபிக்கப்பட்ட ஷைத்தானிடமிருந்து அல்லாஹ்விடம் அடைக்கலம் தேடுகிறேன்.`, si: `ශාපිත ෂෙයිතාන්ගෙන් අල්ලාහ්ගෙන් රැකවරණය පතමි.` },
  bad_p2: { en: `He should also turn onto his other side, and if he wishes, pray two rakat. He should not mention or interpret the dream, for the shaytan hopes it will trouble him. A good dream, by contrast, may be shared only with those who love him.`, ms: `Hendaklah dia juga membalikkan diri kepada sisi yang lain, dan jika mahu, tunaikan dua rakaat. Dia tidak boleh menceritakan atau mentafsirkan mimpi itu, kerana syaitan berharap ia akan mengganggunya. Sebaliknya, mimpi yang baik hanya boleh dikongsi dengan mereka yang mencintainya.`, tur: `Ayrıca diğer yanına dönsün ve dilerse iki rekat namaz kılsın. Rüyayı ne başkasına söylesin ne de yorumlatsın; şeytan onu tedirgin etmesini umar. Güzel rüya ise ancak kişiyi seven kimselere anlatılır.`, urd: `اسے دوسری کروٹ پر بھی مڑ جانا چاہیے، اور اگر چاہے تو دو رکعتیں پڑھے۔ نہ خواب کا ذکر کرے، نہ اس کی تعبیر پوچھے، کیونکہ شیطان چاہتا ہے کہ وہ اسے پریشان کرے۔ اس کے برعکس، اچھا خواب صرف اسے سنایا جائے جو اس سے محبت کرتا ہو۔`, ben: `তার উচিত অপর পাশ ফিরে যাওয়া, এবং চাইলে দুই রাকাত নামাজ পড়া। সে যেন স্বপ্নের কথা না বলে বা তার তাফসির না করে, কারণ শয়তান চায় এটি তাকে কষ্ট দিক। অপরদিকে, ভালো স্বপ্ন শুধু তাদেরই বলা যাবে যারা তাকে ভালোবাসে।`, fas: `همچنین به پهلوی دیگر بگردد و اگر خواست، دو رکعت نماز بگزارد. رؤیای بد را نه بازگو کند و نه تعبیر بخواهد، زیرا شیطان می‌خواهد او را برنجاند. برخلاف آن، رؤیای نیک را تنها با کسی که او را دوست دارد در میان می‌گذارد.`, zh: `亦当翻至另一侧，愿则可礼两拜。梦不当告人亦不当求解，恶魔冀之忧扰。反之，善梦仅告所爱之人。`, yue: `亦當翻至另一側，願則可禮兩拜。夢不當告人亦不當求解，惡魔冀之憂擾。反之，善夢僅告所愛之人。`, ja: `また反対側に寝返り、望むなら二ラカア礼拝せよ。夢を他者に語らず、解釈も求めてはならない。シャイターンはそれで彼を悩ませようと望む。良い夢は、逆に愛する者にのみ話してよい。`, ru: `Пусть также перевернётся на другой бок и, если хочет, совершит два ракята. Не следует рассказывать или толковать этот сон, ибо шайтан желает встревожить им. Добрый же сон, напротив, можно рассказывать только тем, кто его любит.`, es: `Debe también volverse hacia el otro lado y, si lo desea, rezar dos rakat. No debe contar ni pedir interpretación del sueño, pues el shaytán espera que le atormente. El buen sueño, en cambio, sólo se comparte con quienes le aman.`, ko: `그는 또한 반대편으로 몸을 돌리고, 원한다면 두 라카아를 예배해야 한다. 그 꿈을 언급하거나 해석해서도 안 된다. 샤이딴은 그것으로 그를 괴롭히기를 바라기 때문이다. 반대로 좋은 꿈은 자신을 사랑하는 이에게만 말할 수 있다.`, ta: `மேலும் அவர் மற்றொரு புறமாக திரும்பட்டும், விரும்பினால் இரண்டு ரக்அத்துகள் தொழட்டும். அந்தக் கனவை யாருக்கும் சொல்லவேண்டாம், விளக்கம் கேட்கவேண்டாம், ஏனெனில் ஷைத்தான் அதனால் அவரைத் தொந்தரவு செய்ய விரும்புகிறது. மாறாக, நல்ல கனவை தன்னை நேசிப்பவர்களுடன் மட்டுமே பகிர வேண்டும்.`, si: `ඔහු අනෙක් පැත්තට හැරී, කැමති නම් රකාත් දෙකක් නමස්කාර කරන්න. සිහිනය කිසිවෙකුට නොකියන්න, එහි අර්ථය ද නොපරීක්‍ෂා කරන්න; ෂෙයිතාන් එයින් ඔහුට කරදර කිරීමට බලාපොරොත්තු වේ. ඊට වෙනස්ව, යහපත් සිහිනය තමන්ට ප්‍රිය අය සමඟ පමණක් බෙදාගත හැක.` },
  bad_source: { en: `Source: al-Bukhari 3292, Muslim 2261 (Abu Salama, Abu Qatada, Jabir).`, ms: `Sumber: al-Bukhari 3292, Muslim 2261 (Abu Salamah, Abu Qatadah, Jabir).`, tur: `Kaynak: Buhârî 3292, Müslim 2261 (Ebû Seleme, Ebû Katâde, Câbir).`, urd: `ماخذ: بخاری ۳۲۹۲، مسلم ۲۲۶۱ (ابو سلمہ، ابو قتادہ، جابر)۔`, ben: `উৎস: বুখারি ৩২৯২, মুসলিম ২২৬১ (আবু সালামা, আবু কাতাদা, জাবির)।`, fas: `منبع: بخاری ۳۲۹۲، مسلم ۲۲۶۱ (ابوسلمه، ابوقتاده، جابر).`, zh: `出处：布哈里 3292、穆斯林 2261（艾布·萨莱麦、艾布·卡塔达、贾比尔）。`, yue: `出處：布哈里 3292、穆斯林 2261（艾布·薩萊麥、艾布·卡塔達、賈比爾）。`, ja: `出典：ブハーリー 3292、ムスリム 2261（アブー・サラマ、アブー・カターダ、ジャービル）。`, ru: `Источник: аль-Бухари 3292, Муслим 2261 (Абу Салама, Абу Катада, Джабир).`, es: `Fuente: al-Bukhari 3292, Muslim 2261 (Abu Salama, Abu Qatada, Yabir).`, ko: `출처: 알부카리 3292, 무슬림 2261 (아부 살라마, 아부 까따다, 자비르).`, ta: `மூலம்: புகாரி 3292, முஸ்லிம் 2261 (அபூ ஸலமா, அபூ கதாதா, ஜாபிர்).`, si: `මූලාශ්‍රය: බුකාරි 3292, මුස්ලිම් 2261 (අබූ සලමා, අබූ කතාදා, ජාබිර්).` },
  wake_h: { en: `The Du'a on Waking`, ms: `Doa Ketika Terjaga`, tur: `Uyanış Duâsı`, urd: `جاگنے کی دعا`, ben: `জাগার দোয়া`, fas: `دعای بیداری`, zh: `醒时之祷`, yue: `醒時之禱`, ja: `目覚めの祈願`, ru: `Дуа при пробуждении`, es: `La Du'a al despertar`, ko: `잠에서 깨어날 때의 두아`, ta: `விழிக்கும்போது பிரார்த்தனை`, si: `අවදිවීමේ දුආව` },
  wake_translit: { en: `Alhamdulillahi-l ladhi ahyana ba'da ma amatana wa ilayhi-n nushur.`, ms: `Alhamdulillahil-ladhi ahyana ba'da ma amatana wa ilayhin-nushur.`, tur: `El-hamdü lillâhillezî ahyânâ ba'de mâ emâtenâ ve ileyhi'n-nüşûr.`, urd: `الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ۔`, ben: `আলহামদুলিল্লাহিল্লাযি আহইয়ানা বা'দা মা আমাতানা ওয়া ইলাইহিন্-নুশূর।`, fas: `الحمد لله الذی أحیانا بعد ما أماتنا وإلیه النشور.`, zh: `阿勒罕都·利拉希·勒拉齐·阿哈亚那·巴阿达·马·阿马塔那·瓦·伊莱希·努舒尔。`, yue: `阿勒罕都·利拉希·勒拉齊·阿哈亞那·巴阿達·馬·阿馬塔那·瓦·伊萊希·努舒爾。`, ja: `アルハムドゥ・リッラーヒル・ラズィー・アフヤーナー・バアダ・マー・アマーターナー・ワ・イライヒン＝ヌシュール。`, ru: `Аль-хамду лиЛляхи-ль-лязи ахьяна ба'да ма аматана ва илейхи-н-нушур.`, es: `Al-hamdulillahi-l ladhi ahyana ba'da ma amatana wa ilayhi-n nushur.`, ko: `알함두 릴라힐 라디 아흐야나 바으다 마 아마타나 와 일라이힌 누슈르.`, ta: `அல்ஹம்துலில்லாஹில் லதீ அஹ்யானா பஃத மா அமாதனா வ இலைஹின் நுஷூர்.`, si: `අල්හම්දුලිල්ලාහිල් ලදී අහ්යානා බඃද මා අමාතනා ව ඉලෛහින්-නුෂූර්.` },
  wake_meaning: { en: `All praise is due to Allah who has given us life after having caused us to die, and to Him is the return.`, ms: `Segala puji bagi Allah yang telah menghidupkan kami selepas mematikan kami, dan hanya kepada-Nyalah kebangkitan.`, tur: `Bizi öldükten sonra dirilten Allah'a hamd olsun. Dönüş yalnız O'nadır.`, urd: `تمام تعریفیں اللہ کے لیے ہیں جس نے ہمیں مارنے کے بعد زندہ کیا، اور اسی کی طرف لوٹنا ہے۔`, ben: `সকল প্রশংসা আল্লাহর, যিনি আমাদের মৃত্যু ঘটানোর পর আবার জীবিত করেছেন, এবং তাঁরই দিকে প্রত্যাবর্তন।`, fas: `سپاس خدای را که ما را پس از میراندن، زنده گردانید و بازگشت به سوی اوست.`, zh: `一切赞颂归于真主，他已使我们死后复生，唯归于他之复起。`, yue: `一切讚頌歸於真主，他已使我們死後復生，唯歸於他之復起。`, ja: `われらを死せしめた後に生かしたもうたアッラーに、すべての讃美あれ。復活は御身にこそある。`, ru: `Хвала Аллаху, оживившему нас после того, как Он умертвил нас, и к Нему возвращение.`, es: `Alabado sea Al-lah, que nos ha dado vida después de habernos hecho morir, y a Él es el retorno.`, ko: `모든 찬미는 우리를 죽게 하신 뒤 다시 살리신 알라께 있으며, 그분께로 돌아감이 있노라.`, ta: `எல்லாப் புகழும் நம்மை மரிக்கச் செய்த பின் மீண்டும் உயிர்ப்பித்த அல்லாஹ்வுக்கே, மேலும் அவனிடமே திரும்புதல்.`, si: `අප මියගිය පසු නැවත ජීවත් කරවූ අල්ලාහ්ට සියලු ප්‍රශංසා අයත් වේ, නැවත එළැඹීම ඔහු වෙතමය.` },
  wake_p: { en: `The Prophet ﷺ said this every morning, treating the daily cycle of sleep and waking as a rehearsal for the greater sleep and greater rising. Waking with hamd on the tongue turns an ordinary reflex into an act of worship.`, ms: `Nabi ﷺ mengucapkannya setiap pagi, menganggap kitaran harian tidur dan bangun sebagai latihan untuk tidur yang lebih besar dan kebangkitan yang lebih besar. Bangun dengan pujian di lidah menjadikan tindak balas biasa satu amalan ibadah.`, tur: `Peygamber ﷺ her sabah bunu okurdu; günlük uyku ve uyanış döngüsünü daha büyük uyku ve daha büyük dirilişin bir provası olarak görürdü. Dilinde hamd ile uyanmak, sıradan bir refleksi bir ibadete dönüştürür.`, urd: `نبی ﷺ ہر صبح یہ پڑھتے، روزانہ کی نیند اور جاگنے کے چکر کو بڑی نیند اور بڑی قیامت کی مشق سمجھتے۔ زبان پر حمد کے ساتھ جاگنا ایک عام عمل کو عبادت میں بدل دیتا ہے۔`, ben: `নবী ﷺ প্রতি সকালে এটি পড়তেন, ঘুম ও জাগরণের দৈনিক চক্রকে বৃহত্তর ঘুম ও পুনরুত্থানের মহড়া হিসেবে গণ্য করতেন। জিহ্বায় হামদ নিয়ে জাগা একটি সাধারণ প্রতিক্রিয়াকে ইবাদতে পরিণত করে।`, fas: `پیامبر ﷺ هر بامداد این را می‌گفت و چرخهٔ روزانهٔ خواب و بیداری را تمرینی برای خواب بزرگ‌تر و برخاستِ بزرگ‌تر می‌دانست. بیدار شدن با حمد بر زبان، واکنشی عادی را به عبادتی تبدیل می‌کند.`, zh: `先知 ﷺ 每晨诵之，视寐醒之日循为大寐大起之演习。以感颂在舌而醒，令寻常之动作化为拜功。`, yue: `先知 ﷺ 每晨誦之，視寐醒之日循為大寐大起之演習。以感頌在舌而醒，令尋常之動作化為拜功。`, ja: `預言者 ﷺ は毎朝これを唱えられ、日々の眠りと目覚めの循環を、より大いなる眠りと大いなる復活のリハーサルと見なされた。舌にハムドを載せて目覚めることは、普通の反射を礼拝の行為へと変える。`, ru: `Пророк ﷺ произносил это каждое утро, воспринимая ежедневный цикл сна и пробуждения как репетицию большего сна и большего восстания. Пробуждение с хвалой на устах превращает обычный рефлекс в акт поклонения.`, es: `El Profeta ﷺ lo decía cada mañana, tratando el ciclo diario de sueño y vigilia como un ensayo del sueño mayor y la resurrección mayor. Despertar con el hamd en la lengua convierte un reflejo ordinario en un acto de adoración.`, ko: `예언자 ﷺ 께서는 매일 아침 이를 낭송하시며 잠과 깨어남의 일상 순환을 더 큰 잠과 더 큰 부활의 예행으로 삼으셨다. 혀에 함드를 담고 깨어나는 것은 일상적인 반사를 예배 행위로 바꾼다.`, ta: `நபி ﷺ இதை ஒவ்வொரு காலையிலும் ஓதுவார், தினசரி உறக்க-விழிப்பு சுழற்சியை பெரும் உறக்கத்திற்கும் பெரும் எழுச்சிக்கும் ஒத்திகையாக நோக்குவார். நாக்கில் ஹம்துடன் விழிப்பது சாதாரண எதிர்ச்செயலை ஒரு வழிபாட்டு செயலாக மாற்றுகிறது.`, si: `නබි ﷺ තුමා සෑම උදෑසනකම මෙය කීහ, දෛනික නින්ද හා අවදිය මහත් නින්ද හා මහත් නැඟීම සඳහා පුහුණුවක් ලෙස සලකමින්. දිවේ හම්ද් රැගෙන අවදිවීම සාමාන්‍ය ප්‍රතිචාරයක් නමස්කාරයේ ක්‍රියාවක් බවට හරවයි.` },
  wake_source: { en: `Source: al-Bukhari 6312 (Hudhayfah).`, ms: `Sumber: al-Bukhari 6312 (Hudhaifah).`, tur: `Kaynak: Buhârî 6312 (Huzeyfe).`, urd: `ماخذ: بخاری ۶۳۱۲ (حذیفہ)۔`, ben: `উৎস: বুখারি ৬৩১২ (হুযাইফা)।`, fas: `منبع: بخاری ۶۳۱۲ (حذیفه).`, zh: `出处：布哈里 6312（胡宰法）。`, yue: `出處：布哈里 6312（胡宰法）。`, ja: `出典：ブハーリー 6312（フザイファ）。`, ru: `Источник: аль-Бухари 6312 (Хузайфа).`, es: `Fuente: al-Bukhari 6312 (Hudhayfah).`, ko: `출처: 알부카리 6312 (후자이파).`, ta: `மூலம்: புகாரி 6312 (ஹுதைஃபா).`, si: `මූලාශ්‍රය: බුකාරි 6312 (හුදෛෆා).` },
  wisdom_h: { en: `The Wisdom Behind the Sleep Sunnah`, ms: `Hikmah di Sebalik Sunnah Tidur`, tur: `Uyku Sünnetinin Ardındaki Hikmet`, urd: `سونے کی سنت کے پیچھے حکمت`, ben: `ঘুমের সুন্নাহর পিছনের হিকমাহ`, fas: `حکمتِ سنتِ خواب`, zh: `寝之圣行背后之智慧`, yue: `寢之聖行背後之智慧`, ja: `就寝のスンナの背後にある叡智`, ru: `Мудрость Сунны сна`, es: `La sabiduría de la Sunna del sueño`, ko: `잠의 순나 뒤에 있는 지혜`, ta: `உறக்க ஸுன்னாவின் பின்னாலுள்ள ஞானம்`, si: `නින්දේ සුන්නාවේ පිටුපස ඇති ප්‍රඥාව` },
  wisdom_p1: { en: `The Qur'an calls sleep a lesser death: "Allah takes the souls at the moment of their death, and those that have not died in their sleep. He keeps those upon which He has decreed death, and sends the rest back until an appointed term" (al-Zumar 39:42).`, ms: `Al-Quran memanggil tidur sebagai kematian yang lebih kecil: "Allah mengambil nyawa pada waktu kematiannya dan yang belum mati pada waktu tidurnya. Dia menahan yang telah ditetapkan mati padanya dan melepaskan yang lain sehingga tempoh yang ditetapkan" (al-Zumar 39:42).`, tur: `Kur'an, uykuyu küçük ölüm olarak niteler: "Allah, ölüm anlarında canları alır; ölmeyenleri de uykularında (alır). Ölümüne hükmettiği canı tutar, diğerini adı konmuş bir ecele kadar salıverir" (Zümer 39:42).`, urd: `قرآن نیند کو چھوٹی موت کہتا ہے: "اللہ روحوں کو ان کی موت کے وقت قبض کرتا ہے، اور جو نیند میں نہیں مریں، ان کو بھی۔ پھر جس کی موت مقرر کر دی ہو اسے روک لیتا ہے، اور باقی کو ایک مقرر وقت تک بھیج دیتا ہے" (الزمر ۳۹:۴۲)۔`, ben: `কুরআন ঘুমকে ছোট মৃত্যু বলেছে: "আল্লাহ প্রাণসমূহকে গ্রহণ করেন তাদের মৃত্যুর সময়, আর যারা মরেনি তাদেরকে তাদের ঘুমে। অতঃপর যাদের উপর মৃত্যু নির্ধারিত করেছেন তাদেরকে ধরে রাখেন এবং অন্যদের ফিরিয়ে দেন এক নির্ধারিত মেয়াদ পর্যন্ত" (আয-যুমার ৩৯:৪২)।`, fas: `قرآن خواب را مرگی کوچک می‌خواند: «خداوند جان‌ها را در دم مرگشان می‌گیرد و آنان که نمرده‌اند در خوابشان (نیز)؛ پس آن را که مرگش را حکم کرده نگاه می‌دارد و دیگری را تا زمانی معیّن بازمی‌گرداند» (زمر ۳۹:۴۲).`, zh: `《古兰》以寐为小死：「真主于死时收其灵魂，未死者亦于寐时收之。已判死者留之，余者遣归至定期」（曲士 39:42）。`, yue: `《古蘭》以寐為小死：「真主於死時收其靈魂，未死者亦於寐時收之。已判死者留之，餘者遣歸至定期」（曲士 39:42）。`, ja: `クルアーンは眠りを小さな死と呼ぶ。「アッラーは死のときに魂を、また死んでいない者を眠りにおいて（取られる）。彼が死を定められた者を留めおき、その他は定めの期限まで返される」（アッ＝ズマル 39:42）。`, ru: `Коран называет сон малой смертью: «Аллах забирает души в момент их смерти, а тех, что не умерли, во сне. Задерживает Он тех, кому предопределил смерть, а прочих возвращает до установленного срока» (аз-Зумар 39:42).`, es: `El Corán llama al sueño una muerte menor: «Al-lah recoge las almas en el momento de su muerte, y las que no han muerto durante su sueño. Retiene a aquellas cuya muerte ha decretado y envía a las otras hasta un plazo fijado» (az-Zumar 39:42).`, ko: `꾸란은 잠을 작은 죽음이라 부른다: "알라께서는 죽음의 순간에 영혼을 거두시고, 죽지 아니한 자들의 영혼은 그들이 잠들 때 (거두시니). 죽음을 정하신 자는 붙드시고 나머지는 정하여진 기한까지 되돌리시니라" (알주마르 39:42).`, ta: `குர்ஆன் உறக்கத்தை ஒரு சிறிய மரணமாக அழைக்கிறது: "அல்லாஹ் ஆன்மாக்களை அவற்றின் மரண நேரத்தில் கைக்கொள்கிறான், மரணிக்காதவற்றையும் அவற்றின் உறக்கத்தில் கைக்கொள்கிறான். அதன் மேல் மரணத்தை விதித்தவற்றை நிறுத்தி வைக்கிறான், மற்றவற்றை ஒரு நிர்ணயிக்கப்பட்ட காலம் வரை திருப்பி அனுப்புகிறான்" (அஸ்-ஸுமர் 39:42).`, si: `කුර්ආනය නින්ද කුඩා මරණයක් ලෙස හඳුන්වයි: "අල්ලාහ් ආත්මයන් ඔවුන්ගේ මරණයේ මොහොතේ ගනී, මිය නොගිය අයගේ ආත්මය ඔවුන්ගේ නින්දේදී ද (ගනී). ඔහු මරණය නියම කළ අය රඳවා ගනී, අනෙක් අය නියමිත කාලයක් දක්වා නැවත එවයි" (අස්-සුමර් 39:42).` },
  wisdom_p2: { en: `The Prophet's ﷺ etiquette for going to bed is thus not superstition but preparation: purify the body (wudu), fortify the soul with Qur'an (Ayat al-Kursi, the two 'seeking-refuge' surahs, the last verses of al-Baqarah), place life and death consciously in Allah's hand (Bismika Allahumma...). If the soul is returned, one wakes to praise (Alhamdulillah alladhi ahyana...). If it is kept, one has died in the best state a servant can die in, purified, mentioning Allah, on the right side, facing the qiblah.`, ms: `Adab Nabi ﷺ untuk pergi tidur ini bukan khurafat tetapi persiapan: sucikan tubuh (wudhu), kuatkan jiwa dengan al-Quran (Ayat al-Kursi, dua surah al-mu'awwidhatan, dua ayat akhir al-Baqarah), letakkan hidup dan mati dengan sedar di tangan Allah (Bismika Allahumma...). Jika roh dikembalikan, bangun dengan pujian (Alhamdulillah alladhi ahyana...). Jika ia ditahan, orang itu telah mati dalam keadaan terbaik seorang hamba boleh mati, suci, menyebut Allah, di atas sisi kanan, menghadap kiblat.`, tur: `Peygamber'in ﷺ yatağa gitme âdâbı bu sebeple bir hurafe değil, bir hazırlıktır: bedeni temizlemek (abdest), ruhu Kur'an ile kuvvetlendirmek (Âyetü'l-Kürsî, iki muavvezeteyn, Bakara'nın son iki âyeti), hayatı ve ölümü bilinçli olarak Allah'ın eline bırakmak (Bismike'l-Lâhümme...). Ruh iade edildiyse hamd ederek uyanılır (El-hamdü lillâhillezî ahyânâ...). Alıkonduysa kişi, bir kulun ölebileceği en güzel hâlde ölmüş olur: temiz, Allah'ı zikrediyor, sağ tarafında, kıbleye yönelmiş olarak.`, urd: `اسی لیے نبی ﷺ کی سونے کے وقت کی سنت توہم نہیں بلکہ تیاری ہے: بدن کو پاک کرنا (وضو)، روح کو قرآن سے مضبوط کرنا (آیت الکرسی، دونوں معوذتان، سورۃ البقرہ کی آخری دو آیات)، زندگی اور موت کو شعوری طور پر اللہ کے ہاتھ میں رکھنا (بسمک اللهم...)۔ اگر روح لوٹا دی گئی تو حمد کے ساتھ جاگا جاتا ہے (الحمد للہ الذي أحيانا...)۔ اگر روکی گئی تو بندہ بہترین حالت میں فوت ہوا: پاک، اللہ کا ذکر کرتا ہوا، دائیں کروٹ، قبلہ رخ۔`, ben: `তাই নবী ﷺ-এর বিছানায় যাওয়ার আদব কুসংস্কার নয়, বরং প্রস্তুতি: শরীর পবিত্র করা (ওযু), আত্মাকে কুরআন দিয়ে দৃঢ় করা (আয়াতুল কুরসি, দুই মু'আওয়িযাতান, সূরা আল-বাকারার শেষ দুই আয়াত), জীবন-মৃত্যু সচেতনভাবে আল্লাহর হাতে সঁপে দেওয়া (বিসমিকা আল্লাহুম্মা...)। যদি আত্মা ফিরিয়ে দেওয়া হয়, প্রশংসার সাথে জাগা হয় (আলহামদুলিল্লাহিল্লাযি আহইয়ানা...)। যদি রাখা হয়, বান্দা সবচেয়ে ভালো অবস্থায় মরেছে: পবিত্র, আল্লাহকে স্মরণ করা, ডান পাশে, কিবলামুখী।`, fas: `از این رو، آدابِ خفتنِ پیامبر ﷺ خرافه نیست بل آمادگی است: پاکیزه کردنِ بدن (وضو)، تقویت جان با قرآن (آیة الکرسی، دو معوذتین، دو آیه پایانی بقره)، سپردنِ آگاهانه‌ی زندگی و مرگ به دستِ خدا (بسمک اللهم...). اگر روح بازگردانده شود، با حمد بیدار می‌شویم (الحمد لله الذی أحیانا...). اگر نگه داشته شود، بنده در بهترین حال ممکن مرده است: پاک، بر لبْ ذکر خدا، بر پهلوی راست، رو به قبله.`, zh: `故先知 ﷺ 之寝礼非迷信，乃备也：净身（小净），以《古兰》强魂（宝座之节、二求护章、黄牛末二节），以心觉将生死付真主之手（比斯米卡·安拉呼曼……）。若魂归还，以感颂而醒（阿勒罕都·利拉希……）。若被留，仆已死于至美之状：清净、口念真主、右侧卧、面基卜莱。`, yue: `故先知 ﷺ 之寢禮非迷信，乃備也：淨身（小淨），以《古蘭》強魂（寶座之節、二求護章、黃牛末二節），以心覺將生死付真主之手（比斯米卡·安拉呼曼……）。若魂歸還，以感頌而醒（阿勒罕都·利拉希……）。若被留，僕已死於至美之狀：清淨、口念真主、右側臥、面基卜萊。`, ja: `ゆえに預言者 ﷺ の寝床に就く作法は迷信ではなく備えである。身を清め（ウドゥー）、魂をクルアーンで強め（アーヤトゥル＝クルスィー、二つの避難のスーラ、雌牛章の最後の二節）、生と死を意識的にアッラーの御手にゆだねる（ビスミカ・アッラーフンマ……）。魂が返されれば讃美をもって目覚める（アルハムドゥ・リッラーヒル・ラズィー・アフヤーナー……）。留められたなら、僕はしもべが死ねる最善の状態で死んだのだ。清められ、口にアッラーを称え、右を下にし、キブラに向いて。`, ru: `Поэтому этикет Пророка ﷺ при отходе ко сну, не суеверие, а подготовка: очистить тело (омовение), укрепить душу Кораном (аят аль-Курси, две «му'аввизатан», два последних аята аль-Бакара), сознательно вложить жизнь и смерть в руки Аллаха (Би-сми-ка Аллахумма…). Если душа возвращена, встают с хвалой (Аль-хамду лиЛляхи-ль-лязи ахьяна…). Если удержана, раб умер в лучшем состоянии, в каком раб может умереть: очищенным, поминая Аллаха, на правом боку, лицом к кибле.`, es: `Por eso los modales del Profeta ﷺ al ir a la cama no son superstición sino preparación: purificar el cuerpo (wudu), fortalecer el alma con Corán (Ayat al-Kursi, las dos suras de refugio, los dos últimos versículos de al-Baqarah), poner la vida y la muerte conscientemente en la mano de Al-lah (Bismika Al-lahumma...). Si el alma es devuelta, uno despierta con alabanza (Alhamdulillah alladhi ahyana...). Si es retenida, uno ha muerto en el mejor estado en que un siervo puede morir: purificado, mencionando a Al-lah, sobre el lado derecho, orientado hacia la qiblah.`, ko: `그러므로 예언자 ﷺ 께서 잠자리에 드시는 예법은 미신이 아니라 준비이다. 몸을 정결히 하고(우두), 꾸란으로 영혼을 강화하며(아야트 알쿠르시, 두 무아위자탄, 알바카라 마지막 두 절), 삶과 죽음을 의식적으로 알라의 손에 맡긴다(비스미카 알라훔마…). 영혼이 돌아온다면 찬미와 함께 깨어난다(알함두 릴라힐 라디 아흐야나…). 만약 붙들리게 된다면, 그는 종이 죽을 수 있는 가장 좋은 상태로 죽은 것이다. 정결하고, 알라를 상기하며, 오른쪽으로 누워, 키블라를 향한 채로.`, ta: `எனவே நபி ﷺ அவர்களின் படுக்கைக்குச் செல்லும் ஆதாபு மூடநம்பிக்கை அல்ல, தயாரிப்பாகும்: உடலைத் தூய்மைப்படுத்துதல் (உளூ), குர்ஆனால் ஆன்மாவை பலப்படுத்துதல் (ஆயதுல் குர்ஸி, இரு முஅவ்விதாத்தான், அல்-பகராவின் இறுதி இரு வசனங்கள்), வாழ்வையும் மரணத்தையும் விழிப்புடன் அல்லாஹ்வின் கையில் வைப்பது (பிஸ்மிக அல்லாஹும்ம...). ஆன்மா திரும்பினால், புகழுடன் விழிக்கிறோம் (அல்ஹம்துலில்லாஹில் லதீ அஹ்யானா...). நிறுத்தப்பட்டால், அடியான் ஒரு அடியான் இறக்கக்கூடிய சிறந்த நிலையில் இறந்திருக்கிறார்: தூய்மையாக, அல்லாஹ்வை நினைவுகூர்ந்து, வலப் புறமாக, கிப்லா நோக்கி.`, si: `එබැවින් නබි ﷺ තුමන්ගේ නින්දට යාමේ අදාබ් අන්ධ විශ්වාසයක් නොව සූදානමකි: ශරීරය පිරිසිදු කිරීම (වුදූ), කුර්ආනයෙන් ආත්මය ශක්තිමත් කිරීම (ආයතුල් කුර්සී, දෙ මුඅව්විදතාන්, අල්-බකරාහ්ගේ අවසන් වාක්‍ය දෙක), ජීවිතය හා මරණය දැනුවත්ව අල්ලාහ්ගේ අතට පැවරීම (බිස්මික අල්ලාහුම්ම...). ආත්මය නැවත එවනු ලැබුවේ නම්, ප්‍රශංසාවෙන් අවදි වේ (අල්හම්දුලිල්ලාහිල් ලදී අහ්යානා...). රඳවා ගනු ලැබුවේ නම්, දේවසේවකයෙකුට මිය යා හැකි හොඳම තත්ත්වයේ ඔහු මිය ගොස් ඇත: පිරිසිදුව, අල්ලාහ් සිහිකරමින්, දකුණු පැත්තට හැරී, කිබ්ලාව දෙසට මුහුණ ලා.` },
  wisdom_p3: { en: `This is why the classical scholars called the bedtime Sunnah "the equipment of the traveller," because every night is a rehearsal for the journey none of us can miss.`, ms: `Inilah sebabnya ulama klasik menggelar Sunnah menjelang tidur sebagai "bekalan pengembara," kerana setiap malam ialah latihan untuk perjalanan yang tiada seorang pun daripada kita boleh terlepas.`, tur: `Bu sebeple klasik âlimler yatak Sünnetini "yolcunun azığı" diye anmışlardır; çünkü her gece, hiçbirimizin kaçınamayacağı yolculuğun bir provasıdır.`, urd: `اسی لیے کلاسیکی علماء نے سونے کی سنت کو "مسافر کا زادِ راہ" کہا، کیونکہ ہر رات اُس سفر کی مشق ہے جس سے ہم میں سے کوئی نہیں بچ سکتا۔`, ben: `এই কারণেই ধ্রুপদী আলিমগণ ঘুমের সুন্নাহকে "মুসাফিরের রসদ" বলে অভিহিত করেছেন, কারণ প্রতিটি রাতই সেই যাত্রার মহড়া যা আমাদের কেউ এড়াতে পারবে না।`, fas: `از این‌رو علمای کلاسیک، سنتِ خفتن را «توشهٔ مسافر» نامیده‌اند، زیرا هر شب تمرینی است برای سفری که هیچ‌یک از ما را گریزی از آن نیست.`, zh: `故古典学者称寝之圣行为「行者之资粮」，因每夜皆为吾人皆无可免之旅程之演习。`, yue: `故古典學者稱寢之聖行為「行者之資糧」，因每夜皆為吾人皆無可免之旅程之演習。`, ja: `だからこそ古典学者たちは就寝のスンナを「旅人の装備」と呼んだ。すべての夜は、われらの誰も逃れられぬ旅のリハーサルなのである。`, ru: `Именно поэтому классические учёные называли Сунну сна «снаряжением путника»: каждая ночь, это репетиция путешествия, которого никто из нас не минует.`, es: `Por eso los sabios clásicos llamaron a la Sunna del sueño «el equipaje del viajero», pues cada noche es un ensayo del viaje que ninguno de nosotros puede eludir.`, ko: `그래서 고전 학자들은 잠자리 순나를 "여행자의 준비물"이라 불렀다. 모든 밤은 우리 중 누구도 피할 수 없는 여정의 예행 연습이기 때문이다.`, ta: `இதனாலேயே செவ்வியல் அறிஞர்கள் உறக்க ஸுன்னாவை "பயணியின் தளவாடம்" என்று அழைத்தனர், ஏனெனில் ஒவ்வொரு இரவும் நாம் யாராலும் தவிர்க்க முடியாத பயணத்தின் ஒத்திகையாகும்.`, si: `සම්භාව්‍ය විද්වත්හු නින්දේ සුන්නාව "ගමන් යන්නාගේ පිටිය" ලෙස හැඳින්වූයේ එබැවිනි, මන්ද සෑම රාත්‍රියක්ම අප කිසිවෙකුට මඟහැරිය නොහැකි ගමනකට පුහුණුවකි.` },
  label_transliteration: { en: `Transliteration`, ms: `Transliterasi`, tur: `Okunuşu`, urd: `اردو تلفظ`, ben: `উচ্চারণ`, fas: `آوانویسی`, zh: `拉丁转写`, yue: `拉丁轉寫`, ja: `ローマ字転写`, ru: `Транслитерация`, es: `Transliteración`, ko: `발음 표기`, ta: `ஒலிபெயர்ப்பு`, si: `අකුරු පෙරළුම` },
  label_meaning: { en: `Meaning`, ms: `Makna`, tur: `Anlamı`, urd: `معنی`, ben: `অর্থ`, fas: `معنا`, zh: `意义`, yue: `意義`, ja: `意味`, ru: `Значение`, es: `Significado`, ko: `의미`, ta: `பொருள்`, si: `අර්ථය` },
} as const satisfies Record<string, LangMap>;

export type SleepContentKey = keyof typeof SLEEP_CONTENT;
